import sys

def final_floor(s: str) -> int:
    # Santa starts on the ground floor
    floor = 0
    # Process each instruction character
    for c in s:
        if c == '(':
            floor += 1
        elif c == ')':
            floor -= 1
    return floor

def main():
    s = sys.stdin.readline().strip()
    # Handle empty input safely
    if s is None:
        s = ""
    print(final_floor(s))

if __name__ == "__main__":
    main()

