import sys

def first_basement_position(s: str) -> int:
    floor = 0
    for i, ch in enumerate(s):
        if ch == '(':
            floor += 1
        else:  # ch == ')'
            floor -= 1

        # Check immediately after applying this character
        if floor == -1:
            return i + 1  # 1-based position
    return -1  # The problem guarantees basement will be reached

def main():
    s = sys.stdin.readline().strip()
    print(first_basement_position(s))

if __name__ == "__main__":
    main()

