import sys

def solve(s: str) -> int:
    # Set of visited house coordinates (x, y)
    visited = {(0, 0)}

    # Positions for Santa and Robo-Santa
    pos_santa = (0, 0)
    pos_robo = (0, 0)

    # Movement deltas
    deltas = {
        '^': (0, 1),
        'v': (0, -1),
        '>': (1, 0),
        '<': (-1, 0)
    }

    # Simulate alternating turns
    for i, ch in enumerate(s):
        dx, dy = deltas[ch]
        if i % 2 == 0:
            # Santa moves
            pos_santa = (pos_santa[0] + dx, pos_santa[1] + dy)
            visited.add(pos_santa)
        else:
            # Robo-Santa moves
            pos_robo = (pos_robo[0] + dx, pos_robo[1] + dy)
            visited.add(pos_robo)

    return len(visited)

def main():
    s = sys.stdin.readline().strip()
    print(solve(s))

if __name__ == "__main__":
    main()

