import sys

def is_nice(s: str) -> bool:
    vowels = {'a', 'e', 'i', 'o', 'u'}
    vowel_count = 0
    has_double = False

    n = len(s)

    # Scan once: count vowels and detect adjacent double letters
    for i, ch in enumerate(s):
        if ch in vowels:
            vowel_count += 1
        if i > 0 and ch == s[i - 1]:
            has_double = True

    # Check forbidden substrings
    forbidden = {"ab", "cd", "pq", "xy"}
    has_forbidden = False
    for i in range(n - 1):
        if s[i:i + 2] in forbidden:
            has_forbidden = True
            break

    return vowel_count >= 3 and has_double and not has_forbidden

def main():
    s = sys.stdin.readline().rstrip('\n')
    print(1 if is_nice(s) else 0)

if __name__ == "__main__":
    main()

