import sys

def is_nice_part_two(s: str) -> bool:
    n = len(s)
    if n < 3:
        return False

    # Rule 1: a pair of any two letters appears at least twice without overlapping
    first_pos = {}  # pair -> earliest starting index
    has_pair = False
    for i in range(n - 1):
        pair = s[i:i+2]
        if pair not in first_pos:
            first_pos[pair] = i
        else:
            j = first_pos[pair]
            # Non-overlapping means the second pair starts at least 2 chars after the first starts
            if i - j >= 2:
                has_pair = True
                break

    if not has_pair:
        return False

    # Rule 2: a letter repeats with exactly one letter between them
    for i in range(n - 2):
        if s[i] == s[i+2]:
            return True

    return False


def solve(lines):
    count = 0
    for line in lines:
        s = line.strip()
        if not s:
            continue
        if is_nice_part_two(s):
            count += 1
    return count


def main():
    data = sys.stdin.read().splitlines()
    result = solve(data)
    print(result)

if __name__ == "__main__":
    main()

