import sys
import re

ATTRS = [
    "children", "cats", "samoyeds", "pomeranians", "akitas",
    "vizslas", "goldfish", "trees", "cars", "perfumes"
]

# Comparison rules:
# - cats, trees: aunt_value > target
# - pomeranians, goldfish: aunt_value < target
# - others: aunt_value == target
def matches(aunt_attrs, target):
    for k, v in aunt_attrs.items():
        if k in ("cats", "trees"):
            if not (v > target[k]):
                return False
        elif k in ("pomeranians", "goldfish"):
            if not (v < target[k]):
                return False
        else:
            if not (v == target[k]):
                return False
    return True

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    # Parse target from the first non-empty line.
    # Expected formats (common):
    # 1) "children: 3" lines (10 lines) followed by "Sue X: ..."
    # 2) A single line containing all pairs, e.g. "children: 3, cats: 7, ..."
    # We'll support both by extracting all "name: int" pairs from the beginning.
    known = set(ATTRS)
    target = {}
    idx = 0

    # Collect target pairs until we have all 10 or we hit a Sue line.
    sue_line_re = re.compile(r'^\s*Sue\s+(\d+)\s*:\s*(.*)$', re.IGNORECASE)
    pair_re = re.compile(r'(\w+)\s*:\s*(-?\d+)')

    while idx < len(data) and len(target) < 10:
        line = data[idx].strip()
        if not line:
            idx += 1
            continue
        if sue_line_re.match(line):
            break
        for name, val in pair_re.findall(line):
            if name in known:
                target[name] = int(val)
        idx += 1

    # If target wasn't fully parsed yet, try to parse remaining lines before first Sue.
    while idx < len(data) and len(target) < 10:
        line = data[idx].strip()
        if not line:
            idx += 1
            continue
        if sue_line_re.match(line):
            break
        for name, val in pair_re.findall(line):
            if name in known:
                target[name] = int(val)
        idx += 1

    # If still incomplete, fall back to the classic AoC Day 16 target (part 2).
    # This ensures the program works even if the platform provides only Sue lines.
    if len(target) < 10:
        target = {
            "children": 3,
            "cats": 7,
            "samoyeds": 2,
            "pomeranians": 3,
            "akitas": 0,
            "vizslas": 0,
            "goldfish": 5,
            "trees": 3,
            "cars": 2,
            "perfumes": 1,
        }

    # Parse Aunt Sue lines and find the matching one.
    answer = None
    for j in range(idx, len(data)):
        line = data[j].strip()
        if not line:
            continue
        m = sue_line_re.match(line)
        if not m:
            continue
        sue_id = int(m.group(1))
        rest = m.group(2)

        aunt_attrs = {}
        for name, val in pair_re.findall(rest):
            if name in known:
                aunt_attrs[name] = int(val)

        if matches(aunt_attrs, target):
            answer = sue_id
            break

    if answer is None:
        # If no match found, output nothing (or could output -1).
        # Problem expects a valid match.
        return
    sys.stdout.write(str(answer))

if __name__ == "__main__":
    solve()

