import sys

TARGET = {
    "children": 3,
    "cats": 7,
    "samoyeds": 2,
    "pomeranians": 3,
    "akitas": 0,
    "vizslas": 0,
    "goldfish": 5,
    "trees": 3,
    "cars": 2,
    "perfumes": 1,
}

def parse_line(line: str):
    # Expected format: "Sue X: key1: val1, key2: val2, ..."
    line = line.strip()
    if not line:
        return None

    # Split "Sue X:" from the rest
    try:
        left, right = line.split(":", 1)
    except ValueError:
        return None

    left = left.strip()  # "Sue X"
    parts = left.split()
    if len(parts) < 2:
        return None
    sue_num = int(parts[1])

    right = right.strip()
    if not right:
        return sue_num, {}

    pairs = {}
    # Split by commas into "key: val" segments
    for seg in right.split(","):
        seg = seg.strip()
        if not seg:
            continue
        k, v = seg.split(":")
        pairs[k.strip()] = int(v.strip())
    return sue_num, pairs

def matches_part_two(pairs: dict) -> bool:
    for k, v in pairs.items():
        if k in ("cats", "trees"):
            if v <= TARGET[k]:
                return False
        elif k in ("pomeranians", "goldfish"):
            if v >= TARGET[k]:
                return False
        else:
            if v != TARGET[k]:
                return False
    return True

def solve():
    answer = None
    for line in sys.stdin:
        parsed = parse_line(line)
        if not parsed:
            continue
        sue_num, pairs = parsed
        if matches_part_two(pairs):
            answer = sue_num
            break
    if answer is not None:
        sys.stdout.write(str(answer) + "\n")

if __name__ == "__main__":
    solve()

