import sys

def solve(caps, target=150):
    n = len(caps)
    # dp[k][s] = number of ways to reach sum s using exactly k containers
    dp = [[0] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for c in caps:
        # Descend to avoid reusing the same container multiple times
        for k in range(n - 1, -1, -1):
            row = dp[k]
            next_row = dp[k + 1]
            for s in range(target, c - 1, -1):
                if row[s - c]:
                    next_row[s] += row[s - c]

    # Part 2: minimum number of containers to reach target, and count ways
    k_min = None
    for k in range(n + 1):
        if dp[k][target] > 0:
            k_min = k
            break

    if k_min is None:
        return 0
    return dp[k_min][target]

def main():
    data = sys.stdin.read().strip().split()
    caps = [int(x) for x in data] if data else []
    print(solve(caps, 150))

if __name__ == "__main__":
    main()

