import sys

def solve_part1(target: int) -> int:
    # Find smallest house h such that 10 * sum_of_divisors(h) >= target
    limit = 1
    while True:
        presents = [0] * (limit + 1)
        # Elf e delivers 10*e to every multiple of e
        for e in range(1, limit + 1):
            add = 10 * e
            for m in range(e, limit + 1, e):
                presents[m] += add

        for h in range(1, limit + 1):
            if presents[h] >= target:
                return h

        limit *= 2


def solve_part2(target: int) -> int:
    # Find smallest house h such that sum of (11*e) over elves e dividing h
    # and visiting at most 50 houses: h/e <= 50
    limit = 1
    while True:
        presents = [0] * (limit + 1)
        # Elf e delivers to houses e*k for k=1..50
        for e in range(1, limit + 1):
            add = 11 * e
            # Only first 50 multiples
            for k in range(1, 51):
                m = e * k
                if m > limit:
                    break
                presents[m] += add

        for h in range(1, limit + 1):
            if presents[h] >= target:
                return h

        limit *= 2


