import sys
from collections import defaultdict

def solve(messages):
    if not messages:
        return ""

    L = len(messages[0])
    # Defensive: if lengths differ, only consider the common prefix length
    for s in messages:
        if len(s) != L:
            L = min(L, len(s))

    counts = [defaultdict(int) for _ in range(L)]

    # Count character frequencies per column
    for s in messages:
        for i in range(L):
            counts[i][s[i]] += 1

    # Pick the most frequent character for each column
    answer_chars = []
    for i in range(L):
        best_char = None
        best_count = -1
        for ch, cnt in counts[i].items():
            if cnt > best_count:
                best_count = cnt
                best_char = ch
        answer_chars.append(best_char if best_char is not None else "")

    return "".join(answer_chars)

def main():
    messages = []
    for line in sys.stdin:
        line = line.rstrip("\n")
        if line != "":
            messages.append(line)

    result = solve(messages)
    sys.stdout.write(result + ("\n" if result != "" or messages else ""))

if __name__ == "__main__":
    main()

