def supports_tls(line: str) -> bool:
    line = line.strip()
    if not line:
        return False

    def has_abba(s: str) -> bool:
        # ABBA: s[i] == s[i+3], s[i+1] == s[i+2], and s[i] != s[i+1]
        for i in range(len(s) - 3):
            a, b, c, d = s[i], s[i+1], s[i+2], s[i+3]
            if a == d and b == c and a != b:
                return True
        return False

    in_brackets = False
    seg_start = 0

    has_abba_outside = False
    has_abba_inside = False

    for idx, ch in enumerate(line):
        if ch == '[' or ch == ']':
            segment = line[seg_start:idx]
            if segment:
                if in_brackets:
                    if has_abba(segment):
                        has_abba_inside = True
                else:
                    if has_abba(segment):
                        has_abba_outside = True

            in_brackets = (ch == '[')
            seg_start = idx + 1

            # Early exit if we already know the final outcome can't change
            if has_abba_outside and has_abba_inside:
                return False

    # Last segment after final bracket
    segment = line[seg_start:]
    if segment:
        if in_brackets:
            if has_abba(segment):
                has_abba_inside = True
        else:
            if has_abba(segment):
                has_abba_outside = True

    return has_abba_outside and not has_abba_inside


