import sys

def parse_segments(line: str):
    supernets = []
    hypers = []
    in_brackets = False
    start = 0

    for i, ch in enumerate(line):
        if ch == '[':
            # segment from start to i (exclusive) belongs to supernet
            supernets.append(line[start:i])
            in_brackets = True
            start = i + 1
        elif ch == ']':
            # segment from start to i (exclusive) belongs to hypernet
            hypers.append(line[start:i])
            in_brackets = False
            start = i + 1

    # trailing segment after last bracket
    if start <= len(line):
        if in_brackets:
            hypers.append(line[start:])
        else:
            supernets.append(line[start:])

    return supernets, hypers

def has_abba(segment: str) -> bool:
    # ABBA: s[i] != s[i+1], s[i] == s[i+3], s[i+1] == s[i+2]
    for i in range(len(segment) - 3):
        a, b, c, d = segment[i], segment[i+1], segment[i+2], segment[i+3]
        if a != b and a == d and b == c:
            return True
    return False

def collect_aba_pairs(supernets):
    # Collect required BAB patterns as pairs (b, a) for each ABA (a b a)
    required_babs = set()
    for seg in supernets:
        for i in range(len(seg) - 2):
            a, b, c = seg[i], seg[i+1], seg[i+2]
            if a == c and a != b:
                # ABA: a b a -> BAB: b a b
                required_babs.add((b, a))
    return required_babs

def has_matching_bab(hypers, required_babs) -> bool:
    # BAB: b a b corresponds to window t[i..i+2] where t[i]==t[i+2] and t[i]!=t[i+1]
    for seg in hypers:
        for i in range(len(seg) - 2):
            x, y, z = seg[i], seg[i+1], seg[i+2]
            if x == z and x != y:
                if (x, y) in required_babs:
                    return True
    return False

def solve(lines):
    tls_count = 0
    ssl_count = 0

    for line in lines:
        line = line.strip()
        if not line:
            continue

        supernets, hypers = parse_segments(line)

        # Part One (TLS)
        has_super_abba = any(has_abba(seg) for seg in supernets)
        has_hyper_abba = any(has_abba(seg) for seg in hypers)
        if has_super_abba and not has_hyper_abba:
            tls_count += 1

        # Part Two (SSL)
        required_babs = collect_aba_pairs(supernets)
        if required_babs and has_matching_bab(hypers, required_babs):
            ssl_count += 1

    # The prompt's sample output corresponds to Part Two.
    return ssl_count

def main():
    lines = sys.stdin.read().splitlines()
    result = solve(lines)
    print(result)

if __name__ == "__main__":
    main()

