import sys
import re

def rotate_left(s, steps):
    n = len(s)
    k = steps % n
    if k == 0:
        return s
    return s[k:] + s[:k]

def rotate_right(s, steps):
    n = len(s)
    k = steps % n
    if k == 0:
        return s
    return s[n - k:] + s[:n - k]

def apply_ops(s, ops):
    s = list(s)
    n = len(s)

    for op in ops:
        t = op[0]

        if t == "swap_pos":
            x, y = op[1], op[2]
            s[x], s[y] = s[y], s[x]

        elif t == "swap_letter":
            a, b = op[1], op[2]
            # Swap all occurrences safely (letters are typically unique, but handle generally)
            for i in range(len(s)):
                if s[i] == a:
                    s[i] = b
                elif s[i] == b:
                    s[i] = a

        elif t == "rotate_left":
            steps = op[1]
            s = list(rotate_left("".join(s), steps))

        elif t == "rotate_right":
            steps = op[1]
            s = list(rotate_right("".join(s), steps))

        elif t == "rotate_based":
            ch = op[1]
            idx = s.index(ch)  # index before rotation
            rot = 1 + idx
            if idx >= 4:
                rot += 1
            s = list(rotate_right("".join(s), rot))

        elif t == "reverse":
            x, y = op[1], op[2]
            if x > y:
                x, y = y, x
            s[x:y+1] = reversed(s[x:y+1])

        elif t == "move":
            x, y = op[1], op[2]
            ch = s.pop(x)
            s.insert(y, ch)

        else:
            raise ValueError(f"Unknown operation: {t}")

    return "".join(s)

def parse_input(lines):
    ops = []
    # Regex patterns for each operation
    patterns = [
        ("swap_pos", re.compile(r"^swap position (\d+) with position (\d+)$")),
        ("swap_letter", re.compile(r"^swap letter ([a-zA-Z]) with letter ([a-zA-Z])$")),
        ("rotate_left", re.compile(r"^rotate left (\d+) step(s)?$")),
        ("rotate_right", re.compile(r"^rotate right (\d+) step(s)?$")),
        ("rotate_based", re.compile(r"^rotate based on position of letter ([a-zA-Z])$")),
        ("reverse", re.compile(r"^reverse positions (\d+) through (\d+)$")),
        ("move", re.compile(r"^move position (\d+) to position (\d+)$")),
    ]

    for line in lines:
        line = line.strip()
        if not line:
            continue
        matched = False
        for name, pat in patterns:
            m = pat.match(line)
            if m:
                matched = True
                if name == "swap_pos":
                    ops.append((name, int(m.group(1)), int(m.group(2))))
                elif name == "swap_letter":
                    ops.append((name, m.group(1), m.group(2)))
                elif name in ("rotate_left", "rotate_right"):
                    ops.append((name, int(m.group(1))))
                elif name == "rotate_based":
                    ops.append((name, m.group(1)))
                elif name == "reverse":
                    ops.append((name, int(m.group(1)), int(m.group(2))))
                elif name == "move":
                    ops.append((name, int(m.group(1)), int(m.group(2))))
                else:
                    raise ValueError("Unhandled parse case")
                break
        if not matched:
            raise ValueError(f"Could not parse line: {line}")
    return ops

def main():
    lines = sys.stdin.read().splitlines()
    ops = parse_input(lines)

    # Starting password as specified by the problem statement
    start = "abcdefgh"
    result = apply_ops(start, ops)
    print(result)

if __name__ == "__main__":
    main()

