        ("swap_letter", re.compile(r"^swap letter ([a-zA-Z]) with letter ([a-zA-Z])$")),
        ("rotate_left", re.compile(r"^rotate left (\d+) step(s)?$")),
        ("rotate_right", re.compile(r"^rotate right (\d+) step(s)?$")),
        ("rotate_based", re.compile(r"^rotate based on position of letter ([a-zA-Z])$")),
        ("reverse", re.compile(r"^reverse positions (\d+) through (\d+)$")),
        ("move", re.compile(r"^move position (\d+) to position (\d+)$")),
    ]

    for line in lines:
        line = line.strip()
        if not line:
            continue
        matched = False
        for name, pat in patterns:
            m = pat.match(line)
            if m:
                matched = True
                if name == "swap_pos":
                    ops.append((name, int(m.group(1)), int(m.group(2))))
                elif name == "swap_letter":
                    ops.append((name, m.group(1), m.group(2)))
                elif name in ("rotate_left", "rotate_right"):
                    ops.append((name, int(m.group(1))))
                elif name == "rotate_based":
                    ops.append((name, m.group(1)))
                elif name == "reverse":
                    ops.append((name, int(m.group(1)), int(m.group(2))))
                elif name == "move":
                    ops.append((name, int(m.group(1)), int(m.group(2))))
                else:
                    raise ValueError("Unhandled parse case")
                break
        if not matched:
            raise ValueError(f"Could not parse line: {line}")
    return ops

def main():
    lines = sys.stdin.read().splitlines()
    ops = parse_input(lines)

    # Starting password as specified by the problem statement
    start = "abcdefgh"
    result = apply_ops(start, ops)
    print(result)

