import sys

def solve(program_lines):
    program = []
    for line in program_lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        args = parts[1:]
        program.append((op, args))

    def is_reg(s):
        return len(s) == 1 and s in "abcd"

    def get_value(token, regs):
        if is_reg(token):
            return regs[token]
        return int(token)

    regs = {'a': 7, 'b': 0, 'c': 0, 'd': 0}
    pc = 0
    n = len(program)

    # Safety step limit (puzzle programs are expected to terminate)
    step_limit = 10_000_000
    steps = 0

    while 0 <= pc < n:
        steps += 1
        if steps > step_limit:
            break

        op, args = program[pc]

        if op == 'cpy':
            x, y = args
            if is_reg(y):
                regs[y] = get_value(x, regs)
            pc += 1

        elif op == 'inc':
            x = args[0]
            if is_reg(x):
                regs[x] += 1
            pc += 1

        elif op == 'dec':
            x = args[0]
            if is_reg(x):
                regs[x] -= 1
            pc += 1

        elif op == 'jnz':
            x, y = args
            if get_value(x, regs) != 0:
                pc += get_value(y, regs)
            else:
                pc += 1

        elif op == 'tgl':
            x = args[0]
            offset = get_value(x, regs)
            t = pc + offset
            if 0 <= t < n:
                t_op, t_args = program[t]
                # Toggle based on arity
                if len(t_args) == 1:
                    # inc <-> dec, tgl -> inc, other one-arg -> inc
                    if t_op == 'inc':
                        new_op = 'dec'
                    elif t_op == 'dec':
                        new_op = 'inc'
                    else:
                        new_op = 'inc'
                    program[t] = (new_op, t_args)
                else:
                    # jnz <-> cpy, other two-arg -> jnz
                    if t_op == 'jnz':
                        new_op = 'cpy'
                    elif t_op == 'cpy':
                        new_op = 'jnz'
                    else:
                        new_op = 'jnz'
                    program[t] = (new_op, t_args)
            pc += 1

        else:
            # Unknown op; should not happen
            pc += 1

    return regs['a']

def main():
    lines = sys.stdin.read().splitlines()
    ans = solve(lines)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

