import sys
from collections import deque

def solve(data: str) -> str:
    lines = [line.rstrip("\n") for line in data.splitlines() if line.strip("\n") != ""]
    if not lines:
        return "0"
    grid = [list(line) for line in lines]
    R, C = len(grid), len(grid[0])

    # 1. Parse grid and identify special locations (digits)
    pos = {}
    for r in range(R):
        for c in range(C):
            ch = grid[r][c]
            if '0' <= ch <= '9':
                pos[int(ch)] = (r, c)

    if 0 not in pos:
        # Problem statement guarantees 0 exists; fallback
        return "0"

    digits = sorted(pos.keys())
    # Remap digits to compact indices 0..k-1 (preserve 0 as index 0)
    # Ensure index 0 corresponds to digit 0.
    remap = {}
    inv = []
    remap[0] = 0
    inv.append(0)
    idx = 1
    for d in digits:
        if d == 0:
            continue
        remap[d] = idx
        inv.append(d)
        idx += 1

    k = len(inv)
    if k == 1:
        return "0"

    # Build compact positions list
    comp_pos = [None] * k
    for d, (r, c) in pos.items():
        comp_pos[remap[d]] = (r, c)

    # 2. Precompute shortest path distances between all special locations
    INF = 10**18
    dist = [[INF] * k for _ in range(k)]

    passable = set(['.', '#'])  # placeholder; we'll handle '#' as blocked explicitly

    def bfs(start_idx: int):
        sr, sc = comp_pos[start_idx]
        dists = [[-1] * C for _ in range(R)]
        q = deque()
        dists[sr][sc] = 0
        q.append((sr, sc))

        while q:
            r, c = q.popleft()
            curd = dists[r][c]
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and dists[nr][nc] == -1:
                    cell = grid[nr][nc]
                    if cell != '#':  # '.' and digits are passable
                        dists[nr][nc] = curd + 1
                        q.append((nr, nc))

        for t in range(k):
            tr, tc = comp_pos[t]
            dd = dists[tr][tc]
            dist[start_idx][t] = dd if dd != -1 else INF

    for s in range(k):
        bfs(s)

