            nd = dist[r][c] + 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and dist[nr][nc] == -1:
                    cell = grid[nr][nc]
                    if cell != '#':
                        dist[nr][nc] = nd
                        q.append((nr, nc))
        return dist

    # Run BFS from each special node
    for i, d in enumerate(special_digits):
        sr, sc = pos[d]
        dist_grid = bfs_from(sr, sc)
        for j, d2 in enumerate(special_digits):
            tr, tc = pos[d2]
            dd = dist_grid[tr][tc]
            if dd != -1:
                D[i][j] = dd

