import sys
import re

def parse_program(lines):
    prog = []
    reg_set = {"a", "b", "c", "d"}
    int_re = re.compile(r"^-?\d+$")
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        args = parts[1:]
        # Normalize operands: keep as strings; evaluator will interpret
        prog.append((op, args))
    return prog

def is_register(x):
    return x in {"a", "b", "c", "d"}

def eval_operand(x, regs):
    if is_register(x):
        return regs[x]
    # integer literal
    return int(x)

def check_a(prog, a_value, prefix_len=30, step_budget=2000000):
    regs = {"a": a_value, "b": 0, "c": 0, "d": 0}
    ip = 0
    out_count = 0
    steps = 0

    while 0 <= ip < len(prog):
        if steps >= step_budget:
            return False
        steps += 1

        op, args = prog[ip]

        if op == "cpy":
            x, y = args
            if is_register(y):
                regs[y] = eval_operand(x, regs)
            ip += 1

        elif op == "inc":
            x = args[0]
            if is_register(x):
                regs[x] += 1
            ip += 1

        elif op == "dec":
            x = args[0]
            if is_register(x):
                regs[x] -= 1
            ip += 1

        elif op == "jnz":
            x, y = args
            if eval_operand(x, regs) != 0:
                ip += eval_operand(y, regs)
            else:
                ip += 1

        elif op == "out":
            x = args[0]
            v = eval_operand(x, regs)
            if v not in (0, 1):
                return False
            expected = out_count % 2
            if v != expected:
                return False
            out_count += 1
            if out_count >= prefix_len:
                return True
            ip += 1

        else:
            # Unknown instruction; treat as failure
            return False

    return False

def solve():
    lines = sys.stdin.read().splitlines()
    prog = parse_program(lines)

    # Search lowest positive integer a
    a = 1
    # Initial quick check
    while True:
        if check_a(prog, a, prefix_len=30, step_budget=2000000):
            # Stronger verification
            if check_a(prog, a, prefix_len=100, step_budget=6000000):
                print(a)
                return
        a += 1

if __name__ == "__main__":
    solve()

