import sys
import re

def parse_program(lines):
    prog = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        op = parts[0]
        args = parts[1:]
        prog.append((op, args))
    return prog

def is_int(s):
    return re.fullmatch(r"-?\d+", s) is not None

def val(x, regs):
    if is_int(x):
        return int(x)
    return regs[x]

def toggle_rule(op, argc):
    # AoC 2016 Day 23/25 toggle rules:
    # - inc <-> dec (1-arg)
    # - jnz <-> cpy (2-arg)
    # - out is 1-arg, so toggles like inc/dec: out <-> inc
    if argc == 1:
        if op == "inc":
            return "dec"
        if op == "dec":
            return "inc"
        if op == "out":
            return "inc"
        if op == "tgl":
            return "inc"  # not expected, but follow 1-arg rule
        return "inc"
    else:
        if op == "jnz":
            return "cpy"
        if op == "cpy":
            return "jnz"
        return "jnz"

def run_candidate(original_prog, a_init, need_outputs, max_steps):
    # registers: a,b,c,d
    regs = {"a": a_init, "b": 0, "c": 0, "d": 0}
    prog = [list(ins) for ins in original_prog]  # mutable for toggling
    ip = 0
    out_count = 0
    expected_next = 0  # for out_count=0 expected bit is 0

    steps = 0
    n = len(prog)

    while 0 <= ip < n and steps < max_steps:
        steps += 1
        op, args = prog[ip][0], prog[ip][1:]
        argc = len(args)

        if op == "cpy":
            x, y = args
            if y in regs:  # only copy into register
                regs[y] = val(x, regs)
            ip += 1

        elif op == "inc":
            x = args[0]
            if x in regs:
                regs[x] += 1
            ip += 1

        elif op == "dec":
            x = args[0]
            if x in regs:
                regs[x] -= 1
            ip += 1

        elif op == "jnz":
            x, y = args
            if val(x, regs) != 0:
                ip += val(y, regs)
            else:
                ip += 1

        elif op == "tgl":
            x = args[0]
            target = ip + val(x, regs)
            if 0 <= target < n:
                t_op = prog[target][0]
                t_args = prog[target][1:]
                new_op = toggle_rule(t_op, len(t_args))
                prog[target][0] = new_op
            ip += 1

        elif op == "out":
            x = args[0]
            bit = val(x, regs)
            # Puzzle expects exact 0/1; enforce modulo 2 only if value is not 0/1.
            # But compare exact bit after normalization to 0/1.
            bit = bit & 1
            if bit != expected_next:
                return False
            out_count += 1
            if out_count >= need_outputs:
                return True
            expected_next ^= 1
            ip += 1

        else:
            # Unknown op; fail fast
            return False

    return False

def solve(part2=True):
    lines = sys.stdin.read().splitlines()
    prog = parse_program(lines)

    need_outputs = 50 if part2 else 200  # practical verification length for part 1
    max_steps = 2_000_000  # per candidate safeguard

    a = 1
    while True:
        if run_candidate(prog, a, need_outputs=need_outputs, max_steps=max_steps):
            return a
        a += 1

if __name__ == "__main__":
    # The prompt includes Part Two; solve for Part Two.
    ans = solve(part2=True)
    sys.stdout.write(str(ans) + "\n")

