    adj = {}  # id -> set(neighbors)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        # Expected format: A <-> B, C, D
        left_part, right_part = line.split("<->")
        a = int(left_part.strip())

        neighbors_str = right_part.strip()
        if neighbors_str == "":
            neighbors = []
        else:
            neighbors = [int(x.strip()) for x in neighbors_str.split(",") if x.strip() != ""]

        if a not in adj:
            adj[a] = set()

        for b in neighbors:
            if b not in adj:
                adj[b] = set()
            # Undirected edge
            adj[a].add(b)
            adj[b].add(a)

    # Ensure all nodes are represented (already handled during parsing, but keep safe)
    nodes = set(adj.keys())
    for u in list(adj.keys()):
        nodes.add(u)
        for v in adj[u]:
            nodes.add(v)

