def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    layers = []
    for line in lines:
        depth_str, range_str = line.split(":")
        depth = int(depth_str.strip())
        r = int(range_str.strip())
        layers.append((depth, r))

    severity = 0
    for d, r in layers:
        if r == 1:
            severity += d * r
        else:
            period = 2 * (r - 1)
            if d % period == 0:
                severity += d * r

    print(severity)

