import sys
from collections import deque

def knot_hash_bits(s: str):
    # Convert input to ASCII codes
    lengths = [ord(ch) for ch in s] + [17, 31, 73, 47, 23]

    # Initialize circular list
    nums = list(range(256))
    pos = 0
    skip = 0

    # 64 rounds of the knotting process
    for _ in range(64):
        for L in lengths:
            if L > 1:
                # Reverse sublist of length L starting at pos, wrapping around
                idxs = [(pos + i) % 256 for i in range(L)]
                vals = [nums[i] for i in idxs][::-1]
                for i, v in zip(idxs, vals):
                    nums[i] = v
            pos = (pos + L + skip) % 256
            skip += 1

    # Dense hash: XOR blocks of 16
    dense = []
    for b in range(16):
        x = 0
        for i in range(16):
            x ^= nums[b * 16 + i]
        dense.append(x)

    # Convert dense hash to 128 bits (high-bit first per hex digit)
    bits = []
    for x in dense:
        for shift in range(7, -1, -1):
            bits.append((x >> shift) & 1)
    return bits  # length 128

def solve(key: str) -> int:
    # Build 128x128 grid of used(1)/free(0)
    grid = [[0] * 128 for _ in range(128)]
    for r in range(128):
        bits = knot_hash_bits(f"{key}-{r}")
        grid[r] = bits

    visited = [[False] * 128 for _ in range(128)]
    regions = 0

    # 4-directional adjacency
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(128):
        for c in range(128):
            if grid[r][c] == 1 and not visited[r][c]:
                regions += 1
                visited[r][c] = True
                q = deque([(r, c)])

                while q:
                    cr, cc = q.popleft()
                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 128 and 0 <= nc < 128:
                            if grid[nr][nc] == 1 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

    return regions

def main():
    key = sys.stdin.readline().strip()
    print(solve(key))

if __name__ == "__main__":
    main()

