import sys
import re

def parse_start_values(text: str):
    nums = list(map(int, re.findall(r'-?\d+', text)))
    if len(nums) < 2:
        raise ValueError("Could not parse two starting values.")
    return nums[0], nums[1]

def solve(a0: int, b0: int, pairs: int = 5_000_000) -> int:
    MOD = 2147483647
    FACTOR_A = 16807
    FACTOR_B = 48271

    def next_accepted(prev: int, factor: int, multiple: int) -> int:
        while True:
            prev = (prev * factor) % MOD
            if prev % multiple == 0:
                return prev

    prevA, prevB = a0, b0
    count = 0
    for _ in range(pairs):
        prevA = next_accepted(prevA, FACTOR_A, 4)
        prevB = next_accepted(prevB, FACTOR_B, 8)
        if (prevA & 0xFFFF) == (prevB & 0xFFFF):
            count += 1
    return count

def main():
    data = sys.stdin.read()
    a0, b0 = parse_start_values(data)
    ans = solve(a0, b0)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

