import sys

def parse_changes(s: str):
    s = s.strip()
    if not s:
        return []
    parts = s.split(',')
    changes = []
    for p in parts:
        p = p.strip()
        if p:
            changes.append(int(p))
    return changes

def solve(changes):
    # Part Two: find the first frequency reached twice
    freq = 0
    seen = {freq}
    i = 0
    n = len(changes)

    while True:
        freq += changes[i]
        if freq in seen:
            return freq
        seen.add(freq)
        i = (i + 1) % n

def main():
    data = sys.stdin.read()
    changes = parse_changes(data)
    if not changes:
        return
    ans = solve(changes)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

