import sys

def find_common_letters(ids):
    if not ids:
        return ""
    L = len(ids[0])

    # Map from "id with one position removed" -> first id that produced it
    seen = {}

    for s in ids:
        # If input is malformed with varying lengths, only process consistent ones
        if len(s) != L:
            continue
        for i in range(L):
            reduced = s[:i] + s[i+1:]
            if reduced in seen:
                # The common letters are exactly the reduced string
                return reduced
            seen[reduced] = s
    return ""

def main():
    ids = [line.strip() for line in sys.stdin if line.strip() != ""]
    result = find_common_letters(ids)
    if result != "":
        sys.stdout.write(result + "\n")

if __name__ == "__main__":
    main()

