import sys
import re

def parse_claims(lines):
    claims = []
    pattern = re.compile(r'#(\d+)\s*@\s*(\d+),(\d+):\s*(\d+)x(\d+)')
    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = pattern.match(line)
        if not m:
            continue
        cid = int(m.group(1))
        left = int(m.group(2))
        top = int(m.group(3))
        width = int(m.group(4))
        height = int(m.group(5))
        # Use half-open intervals: [x1, x2) and [y1, y2)
        x1, x2 = left, left + width
        y1, y2 = top, top + height
        claims.append((cid, x1, x2, y1, y2))
    return claims

def overlaps(a, b):
    # a and b are (id, x1, x2, y1, y2)
    _, ax1, ax2, ay1, ay2 = a
    _, bx1, bx2, by1, by2 = b
    return (ax1 < bx2 and ax2 > bx1 and ay1 < by2 and ay2 > by1)

def solve(lines):
    claims = parse_claims(lines)
    n = len(claims)
    for i in range(n):
        intact = True
        for j in range(n):
            if i == j:
                continue
            if overlaps(claims[i], claims[j]):
                intact = False
                break
        if intact:
            return str(claims[i][0])
    return ""

def main():
    lines = sys.stdin.read().splitlines()
    result = solve(lines)
    if result != "":
        sys.stdout.write(result)

if __name__ == "__main__":
    main()

