import sys
import re

def solve(lines):
    records = []
    # Regex to extract timestamp and event details
    ts_re = re.compile(r"\[(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})\] (.*)")
    guard_re = re.compile(r"Guard #(\d+) begins shift")

    for line in lines:
        line = line.strip()
        if not line:
            continue
        m = ts_re.match(line)
        if not m:
            continue
        y, mo, d, hh, mm, event_text = m.groups()
        timestamp = (int(y), int(mo), int(d), int(hh), int(mm))
        gm = guard_re.search(event_text)
        if gm:
            guard_id = int(gm.group(1))
            records.append((timestamp, "begins", guard_id))
        elif event_text == "falls asleep":
            records.append((timestamp, "sleep", None))
        elif event_text == "wakes up":
            records.append((timestamp, "wake", None))
        else:
            # Unknown line; ignore
            continue

    # Sort chronologically
    records.sort(key=lambda x: x[0])

    # sleep_minutes[guard_id][minute] = number of times asleep at that minute
    sleep_minutes = {}

    current_guard = None
    sleep_start = None

    for ts, typ, guard_id in records:
        minute = ts[4]  # minute within the hour (00-59)
        if typ == "begins":
            current_guard = guard_id
            if current_guard not in sleep_minutes:
                sleep_minutes[current_guard] = [0] * 60
        elif typ == "sleep":
            sleep_start = minute
        elif typ == "wake":
            # Update for minutes in [sleep_start, minute)
            # Guard counts as asleep on fall minute, awake on wake minute.
            guard_arr = sleep_minutes[current_guard]
            for m in range(sleep_start, minute):
                guard_arr[m] += 1

    # Strategy 1: guard with most total minutes asleep
    best_guard = None
    best_total = -1
    for gid, arr in sleep_minutes.items():
        total = sum(arr)
        if total > best_total:
            best_total = total
            best_guard = gid

    # Find minute best_guard is most frequently asleep
    best_minute = 0
    best_count = -1
    arr = sleep_minutes[best_guard]
    for m in range(60):
        c = arr[m]
        if c > best_count:
            best_count = c
            best_minute = m

    return str(best_guard * best_minute)

def main():
    lines = sys.stdin.read().splitlines()
    print(solve(lines))

if __name__ == "__main__":
    main()

