import sys
import re
from collections import deque

def solve(data: str) -> int:
    lines = [ln.strip() for ln in data.strip().splitlines() if ln.strip()]
    clay = set()
    min_y = 10**18
    max_y = -10**18

    pat = re.compile(r'([xy])=(\d+), ([xy])=(\d+)\.\.(\d+)')
    for ln in lines:
        m = pat.match(ln)
        if not m:
            continue
        a1, v1, a2, lo, hi = m.group(1), int(m.group(2)), m.group(3), int(m.group(4)), int(m.group(5))
        if a1 == 'x' and a2 == 'y':
            x = v1
            for y in range(lo, hi + 1):
                clay.add((x, y))
                min_y = min(min_y, y)
                max_y = max(max_y, y)
        elif a1 == 'y' and a2 == 'x':
            y = v1
            for x in range(lo, hi + 1):
                clay.add((x, y))
                min_y = min(min_y, y)
                max_y = max(max_y, y)
        else:
            # Should not happen for valid inputs
            pass

    spring = (500, 0)
    flowing = set()
    resting = set()

    # Helper: cell is blocked (clay or resting water)
    def is_blocked(x, y):
        return (x, y) in clay or (x, y) in resting

    # We simulate using an explicit stack to avoid recursion depth issues.
    # Each task is a source position where water is trying to flow from.
    stack = [spring]

    # To reduce redundant work, we can track sources we've already processed
    # when they are at a stable "support" level. However, correctness is more
    # important than aggressive pruning; still, we avoid infinite loops by
    # only re-adding sources when they can potentially change state.
    in_stack = {spring}

    while stack:
        x, y = stack.pop()
        in_stack.discard((x, y))

        # Move downward as far as possible.
        cur_y = y
        while True:
            if cur_y > max_y:
                break
            below = (x, cur_y + 1)
            here = (x, cur_y)

            if here not in clay and here not in resting:
                flowing.add(here)

            if below in clay or below in resting:
                # Supported; stop falling.
                break

            # If below is not blocked, continue falling.
            cur_y += 1

        # If we fell out of bounds, nothing to settle.
        if cur_y > max_y:
            continue

        # Now at row cur_y where below is blocked by clay/resting.
        support_y = cur_y

        # Spread left and right on support_y.
        # Determine boundaries and whether each side leaks.
        left = x
        left_leak = False
        while True:
            if (left, support_y) in clay:
                break
            flowing.add((left, support_y))
            if support_y + 1 > max_y:
                # Below is outside scan; treat as leak (water can fall forever).
                left_leak = True
                break
            if not is_blocked(left, support_y + 1):
                left_leak = True
                break
            left -= 1

        right = x
        right_leak = False
        while True:
            if (right, support_y) in clay:
                break
            flowing.add((right, support_y))
            if support_y + 1 > max_y:
                right_leak = True
                break
            if not is_blocked(right, support_y + 1):
                right_leak = True
                break
            right += 1

        # If both sides are bounded by clay, settle the whole span.
        if not left_leak and not right_leak:
            # left wall is at left (clay), right wall is at right (clay)
            # Water occupies between them: (left+1 .. right-1)
            for xx in range(left + 1, right):
                if (xx, support_y) not in clay:
                    flowing.discard((xx, support_y))
                    resting.add((xx, support_y))
            # After settling, try to fill upward.
            up = (x, support_y - 1)
            if up not in clay and up not in resting and up[1] >= min_y:
                if up not in in_stack:
                    stack.append(up)
                    in_stack.add(up)
        else:
            # At least one side leaks: keep as flowing and recurse from leak points.
            # For each leaking side, find the first position where below is open.
            if left_leak:
                lx = x
                while True:
                    if (lx, support_y) in clay:
                        break
                    if support_y + 1 > max_y:
                        break
                    if not is_blocked(lx, support_y + 1):
                        leak_src = (lx, support_y)
                        if leak_src not in clay and leak_src not in resting and leak_src[1] >= min_y:
                            if leak_src not in in_stack:
                                stack.append(leak_src)
                                in_stack.add(leak_src)
                        break
                    lx -= 1

            if right_leak:
                rx = x
                while True:
                    if (rx, support_y) in clay:
                        break
                    if support_y + 1 > max_y:
                        break
                    if not is_blocked(rx, support_y + 1):
                        leak_src = (rx, support_y)
                        if leak_src not in clay and leak_src not in resting and leak_src[1] >= min_y:
                            if leak_src not in in_stack:
                                stack.append(leak_src)
                                in_stack.add(leak_src)
                        break
                    rx += 1

    # Count reachable tiles within y-range.
    ans = 0
    for (x, y) in flowing:
        if min_y <= y <= max_y:
            ans += 1
    for (x, y) in resting:
        if min_y <= y <= max_y:
            ans += 1
    return ans

def main():
    data = sys.stdin.read()
    print(solve(data))

if __name__ == "__main__":
    main()

