def run_divisor_sum(N):
    # Sum of positive divisors of N
    if N <= 0:
        return 0
    s = 0
    r = int(math.isqrt(N))
    for d in range(1, r + 1):
        if N % d == 0:
            s += d
            q = N // d
            if q != d:
