import sys
from collections import deque

def solve(regex: str) -> int:
    regex = regex.strip()
    if regex.startswith('^'):
        regex = regex[1:]
    if regex.endswith('$'):
        regex = regex[:-1]

    # Movement deltas
    delta = {
        'N': (0, -1),
        'S': (0, 1),
        'E': (1, 0),
        'W': (-1, 0),
    }

    # Adjacency list for the room graph (undirected edges)
    adj = {}  # room -> set(neighbors)

    def add_edge(a, b):
        if a not in adj:
            adj[a] = set()
        if b not in adj:
            adj[b] = set()
        adj[a].add(b)
        adj[b].add(a)

    # Current set of possible positions after processing prefix
    cur = {(0, 0)}

    # Stack frames for parentheses:
    # each frame: (start_set, acc_set)
    stack = []

    for ch in regex:
        if ch in delta:
            dx, dy = delta[ch]
            next_cur = set()
            for (x, y) in cur:
                nx, ny = x + dx, y + dy
                a = (x, y)
                b = (nx, ny)
                add_edge(a, b)
                next_cur.add(b)
            cur = next_cur
        elif ch == '(':
            # Start of a branch group
            stack.append((set(cur), set()))
        elif ch == '|':
            # End one option: accumulate ends, reset to group start
            start_set, acc_set = stack[-1]
            acc_set.update(cur)
            cur = set(start_set)
        elif ch == ')':
            # End group: accumulate last option and pop
            start_set, acc_set = stack.pop()
            acc_set.update(cur)
            cur = acc_set
        else:
            # Should not happen for valid inputs (only N,S,E,W,(,),|)
            pass

    # BFS for shortest door counts
    start = (0, 0)
    dist = {start: 0}
    q = deque([start])

    while q:
        u = q.popleft()
        for v in adj.get(u, ()):
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)

    return max(dist.values()) if dist else 0

def main():
    s = sys.stdin.readline()
    if not s:
        return
    print(solve(s))

if __name__ == "__main__":
    main()

