import sys
from collections import deque

def solve():
    parent = {}
    adj = {}

    # Read all orbit relations until EOF
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        a, b = line.split(')')
        parent[b] = a

        # Build undirected adjacency for Part Two
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, []).append(a)

    # Part One: total number of direct + indirect orbits
    # depth(x) = number of steps from x up to COM
    depth_memo = {'COM': 0}

    def depth(x):
        if x in depth_memo:
            return depth_memo[x]
        p = parent.get(x)
        if p is None:
            # If input is malformed and x has no parent (other than COM), treat as 0
            depth_memo[x] = 0
            return 0
        depth_memo[x] = 1 + depth(p)
        return depth_memo[x]

    total_orbits = 0
    for node in parent:
        if node != 'COM':
            total_orbits += depth(node)

    # Part Two: minimum orbital transfers between objects YOU and SAN are orbiting
    start = parent.get('YOU')
    target = parent.get('SAN')

    if start is None or target is None:
        # Malformed input; no valid transfer possible
        print(0)
        return

    # BFS on undirected graph
    q = deque([start])
    dist = {start: 0}

    while q:
        u = q.popleft()
        if u == target:
            break
        for v in adj.get(u, []):
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)

    print(dist.get(target, 0))

if __name__ == "__main__":
    solve()

