import sys
import math

def best_station_detected(grid_lines):
    asteroids = []
    for y, line in enumerate(grid_lines):
        line = line.rstrip("\n")
        for x, ch in enumerate(line):
            if ch == '#':
                asteroids.append((x, y))

    n = len(asteroids)
    if n <= 1:
        return 0

    best = 0
    for ax, ay in asteroids:
        seen = set()
        for bx, by in asteroids:
            if (bx, by) == (ax, ay):
                continue
            dx = bx - ax
            dy = by - ay
            g = math.gcd(abs(dx), abs(dy))
            dx //= g
            dy //= g
            seen.add((dx, dy))
        best = max(best, len(seen))

    return best

def main():
    grid_lines = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    # If input may contain empty lines, keep only non-empty lines.
    # Problem inputs are typically a contiguous grid without blank lines.
    if not grid_lines:
        print(0)
        return
    print(best_station_detected(grid_lines))

if __name__ == "__main__":
    main()

