import sys
import math
from collections import defaultdict
from math import gcd

def solve(data: str) -> str:
    lines = [line.strip() for line in data.splitlines() if line.strip() != ""]
    if not lines:
        return ""

    asteroids = []
    for y, row in enumerate(lines):
        for x, ch in enumerate(row):
            if ch == '#':
                asteroids.append((x, y))

    n = len(asteroids)
    if n == 0:
        return ""

    def reduced_direction(sx, sy, tx, ty):
        dx = tx - sx
        dy = ty - sy
        g = gcd(abs(dx), abs(dy))
        return (dx // g, dy // g)

    # Part 1: find best asteroid by counting unique reduced directions
    best = None
    best_count = -1
    for i in range(n):
        sx, sy = asteroids[i]
        seen = set()
        for j in range(n):
            if i == j:
                continue
            tx, ty = asteroids[j]
            seen.add(reduced_direction(sx, sy, tx, ty))
        cnt = len(seen)
        if cnt > best_count:
            best_count = cnt
            best = (sx, sy)

    sx, sy = best

    # Part 2: group asteroids by direction from best station, store distance
    dir_map = defaultdict(list)  # dir -> list of (dist2, x, y)
    for (tx, ty) in asteroids:
        if (tx, ty) == (sx, sy):
            continue
        d = reduced_direction(sx, sy, tx, ty)
        dx = tx - sx
        dy = ty - sy
        dist2 = dx * dx + dy * dy
        dir_map[d].append((dist2, tx, ty))

    # Sort each direction by increasing distance (closest first)
    for d in list(dir_map.keys()):
        dir_map[d].sort(key=lambda t: t[0])

    # Order directions clockwise starting from "up" (0,-1)
    # Use angle = atan2(dx, -dy) so that:
    # - up (0,-1) => atan2(0, 1) = 0
    # - right (1,0) => atan2(1, 0) = pi/2
    # - down (0,1) => atan2(0, -1) = pi
    # - left (-1,0) => atan2(-1, 0) = -pi/2 => normalized to 3pi/2
    def angle_key(d):
        dx, dy = d
        ang = math.atan2(dx, -dy)
        if ang < 0:
            ang += 2 * math.pi
        return ang

    directions_ordered = sorted(dir_map.keys(), key=angle_key)

    # Simulate vaporization
    pos = {d: 0 for d in directions_ordered}
    vaporized = 0
    target = 200
    last_x = last_y = None

    while vaporized < target:
        progressed = False
        for d in directions_ordered:
            idx = pos[d]
            if idx < len(dir_map[d]):
                _, x, y = dir_map[d][idx]
                pos[d] = idx + 1
                vaporized += 1
                progressed = True
                last_x, last_y = x, y
                if vaporized == target:
                    break
        if not progressed:
            break  # fewer than target asteroids

    if last_x is None:
        return ""
    return str(last_x * 100 + last_y)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

