def parse_grid(lines):
    grid = []
    for line in lines:
        line = line.strip()
        grid.append([c == '#' for c in line])
    return grid

def grid_to_state(grid):
    # Map (r,c) -> bit index i = r*5 + c, row-major
    state = 0
    for r in range(5):
        for c in range(5):
            if grid[r][c]:
                state |= 1 << (r * 5 + c)
    return state

def state_to_grid(state):
    grid = [[False] * 5 for _ in range(5)]
    for r in range(5):
        for c in range(5):
            i = r * 5 + c
            grid[r][c] = (state >> i) & 1 == 1
    return grid

def next_state(state):
    # Compute next minute using simultaneous update rules
    grid = state_to_grid(state)
    new_grid = [[False] * 5 for _ in range(5)]

    for r in range(5):
        for c in range(5):
            adj = 0
            if r > 0 and grid[r - 1][c]:
                adj += 1
            if r < 4 and grid[r + 1][c]:
                adj += 1
            if c > 0 and grid[r][c - 1]:
                adj += 1
            if c < 4 and grid[r][c + 1]:
                adj += 1

            if grid[r][c]:
                new_grid[r][c] = (adj == 1)
            else:
                new_grid[r][c] = (adj == 1 or adj == 2)

    return grid_to_state(new_grid)

