import sys

def solve():
    lines = [line.strip() for line in sys.stdin.read().strip().splitlines() if line.strip()]
    if len(lines) != 5:
        return
    grid = [[c == '#' for c in row] for row in lines]

    # Map (r,c) -> bit index 0..24
    def idx(r, c):
        return r * 5 + c

    CENTER = idx(2, 2)

    # Precompute adjacency for each tile (excluding center):
    # For each tile i, store list of (deltaLevel, neighborBitIndex) that contribute to adjacency count.
    adj = [[] for _ in range(25)]
    for r in range(5):
        for c in range(5):
            i = idx(r, c)
            if i == CENTER:
                continue
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if nr == 2 and nc == 2:
                    # Moving into the center: fan out into inner level (level +1)
                    # Determine which side we came from to select the corresponding edge in inner grid.
                    if dr == -1 and dc == 0:
                        # from above center -> inner level top row (row 0, all cols)
                        for cc in range(5):
                            adj[i].append((+1, idx(0, cc)))
                    elif dr == 1 and dc == 0:
                        # from below center -> inner level bottom row (row 4, all cols)
                        for cc in range(5):
                            adj[i].append((+1, idx(4, cc)))
                    elif dr == 0 and dc == -1:
                        # from left of center -> inner level left column (col 0, all rows)
                        for rr in range(5):
                            adj[i].append((+1, idx(rr, 0)))
                    elif dr == 0 and dc == 1:
                        # from right of center -> inner level right column (col 4, all rows)
                        for rr in range(5):
                            adj[i].append((+1, idx(rr, 4)))
                elif 0 <= nr < 5 and 0 <= nc < 5:
                    # Same level neighbor (level delta 0), but skip center tile (it never holds bugs)
                    j = idx(nr, nc)
                    if j != CENTER:
                        adj[i].append((0, j))
                else:
                    # Off-grid: neighbor comes from outer level (level -1)
                    # Map direction to the tile adjacent to center in the outer grid.
                    if nr < 0:
                        # up off-grid -> outer level tile (1,2)
                        adj[i].append((-1, idx(1, 2)))
                    elif nr >= 5:
                        # down off-grid -> outer level tile (3,2)
                        adj[i].append((-1, idx(3, 2)))
                    elif nc < 0:
                        # left off-grid -> outer level tile (2,1)
                        adj[i].append((-1, idx(2, 1)))
                    elif nc >= 5:
                        # right off-grid -> outer level tile (2,3)
                        adj[i].append((-1, idx(2, 3)))

    # Initialize states: depth -> 25-bit mask (center bit always 0)
    # Use a fixed range for simplicity/safety.
    minutes = 200
    min_depth = -minutes - 2
    max_depth = minutes + 2
    depth_count = max_depth - min_depth + 1

    # states array indexed by depth offset
    states = [0] * depth_count
    mask0 = 0
    for r in range(5):
        for c in range(5):
            if r == 2 and c == 2:
                continue
            if grid[r][c]:
                mask0 |= 1 << idx(r, c)
    states[0 - min_depth] = mask0

    # Precompute bit positions for tiles excluding center
    tile_indices = [i for i in range(25) if i != CENTER]

    for _ in range(minutes):
        next_states = [0] * depth_count
        for di in range(depth_count):
            cur_mask = states[di]
            if cur_mask == 0:
                # Still need to compute because neighbors from other depths may create bugs here.
                # We'll proceed anyway; counting uses states at di+delta.
                pass

            # For each tile, count adjacent bugs across levels
            for i in tile_indices:
                adj_count = 0
                for delta, nb in adj[i]:
                    nd = di + delta
                    if 0 <= nd < depth_count:
                        if (states[nd] >> nb) & 1:
                            adj_count += 1
                has_bug = (cur_mask >> i) & 1
                if has_bug:
                    if adj_count == 1:
                        next_states[di] |= 1 << i
                else:
                    if adj_count == 1 or adj_count == 2:
                        next_states[di] |= 1 << i
        states = next_states

    # Count total bugs across all depths
    total = 0
    for m in states:
        total += m.bit_count()
    print(total)

if __name__ == "__main__":
    solve()

