import sys

def solve():
    # Read all lines until EOF, ignoring blank lines
    instructions = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        action = line[0]
        value = int(line[1:])
        instructions.append((action, value))

    # Ship state: position relative to start
    x, y = 0, 0  # x: east(+)/west(-), y: north(+)/south(-)

    # Facing direction: 0=E, 1=S, 2=W, 3=N (clockwise order)
    dirs = ['E', 'S', 'W', 'N']
    dir_idx = 0  # starts facing east

    for action, value in instructions:
        if action == 'N':
            y += value
        elif action == 'S':
            y -= value
        elif action == 'E':
            x += value
        elif action == 'W':
            x -= value
        elif action == 'L':
            # Turning left by degrees; input is in multiples of 90
            dir_idx = (dir_idx - (value // 90)) % 4
        elif action == 'R':
            # Turning right by degrees; input is in multiples of 90
            dir_idx = (dir_idx + (value // 90)) % 4
        elif action == 'F':
            # Move forward in the current facing direction
            d = dirs[dir_idx]
            if d == 'E':
                x += value
            elif d == 'W':
                x -= value
            elif d == 'N':
                y += value
            else:  # 'S'
                y -= value

    # Manhattan distance from starting position
    print(abs(x) + abs(y))

if __name__ == "__main__":
    solve()

