def solve():
    instructions = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        action = line[0]
        value = int(line[1:])
        instructions.append((action, value))

    # Ship position (absolute)
    sx, sy = 0, 0
    # Waypoint position relative to ship
    wx, wy = 10, 1

    for action, value in instructions:
        if action == 'N':
            wy += value
        elif action == 'S':
            wy -= value
        elif action == 'E':
            wx += value
        elif action == 'W':
            wx -= value
        elif action == 'F':
            sx += wx * value
            sy += wy * value
        elif action in ('L', 'R'):
            # Rotations are in multiples of 90 degrees in the puzzle
            steps = (value // 90) % 4
            if action == 'R':
                # Convert clockwise to equivalent number of left (CCW) rotations
                steps = (-steps) % 4

            for _ in range(steps):
                # 90 degrees left (CCW): (x, y) -> (-y, x)
                wx, wy = -wy, wx

    print(abs(sx) + abs(sy))

if __name__ == "__main__":
    solve()

