import sys

def solve():
    lines = [line.strip() for line in sys.stdin if line.strip()]

    instructions = []
    for line in lines:
        if line.startswith("mask = "):
            instructions.append(("mask", line.split(" = ")[1]))
        else:
            # mem[addr] = value
            left, right = line.split(" = ")
            addr = int(left[left.find("[") + 1:left.find("]")])
            val = int(right)
            instructions.append(("mem", addr, val))

    # Part 2: address decoding with floating bits
    mem = {}

    ones_mask = 0
    floating_positions = []

    for inst in instructions:
        if inst[0] == "mask":
            mask = inst[1]
            ones_mask = 0
            floating_positions = []
            # mask[0] is bit 35, mask[35] is bit 0
            for i, ch in enumerate(mask):
                bit = 35 - i
                if ch == '1':
                    ones_mask |= (1 << bit)
                elif ch == 'X':
                    floating_positions.append(bit)
        else:
            _, addr, val = inst
            base = addr | ones_mask

            # Generate all addresses from floating bits
            k = len(floating_positions)
            for combo in range(1 << k):
                a = base
                for i, bit in enumerate(floating_positions):
                    if (combo >> i) & 1:
                        a |= (1 << bit)
                    else:
                        a &= ~(1 << bit)
                mem[a] = val

    print(sum(mem.values()))

if __name__ == "__main__":
    solve()

