import sys

def rambunctious_recitation(start_numbers, target_turn=2020):
    # last[x] = most recent turn x was spoken
    # prev[x] = turn x was spoken immediately before last[x] (older occurrence)
    last = {}
    prev = {}

    # Initialize with starting numbers (turns are 1-indexed)
    for i, x in enumerate(start_numbers):
        t = i + 1
        if x in last:
            prev[x] = last[x]
        last[x] = t

    # If target is within starting numbers
    if len(start_numbers) >= target_turn:
        return start_numbers[target_turn - 1]

    last_spoken = start_numbers[-1]
    # Iterate from the next turn after initialization up to target_turn
    for t in range(len(start_numbers) + 1, target_turn + 1):
        x = last_spoken
        if x not in prev:
            y = 0
        else:
            y = last[x] - prev[x]

        # Update tracking for y at turn t
        if y in last:
            prev[y] = last[y]
        last[y] = t

        last_spoken = y

    return last_spoken

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    start_numbers = [int(tok.strip()) for tok in line.split(',') if tok.strip() != '']
    ans = rambunctious_recitation(start_numbers, 2020)
    print(ans)

if __name__ == "__main__":
    main()

