import sys

def rambunctious_recitation(start_numbers, target_turn):
    # Track the last two turns each number was spoken:
    # last_turn[x] = most recent turn x was spoken
    # prev_turn[x] = turn before that (second most recent), or 0 if none
    last_turn = {}
    prev_turn = {}

    # Initialize with starting numbers (turns are 1-indexed)
    for i, x in enumerate(start_numbers, start=1):
        if x in last_turn:
            prev_turn[x] = last_turn[x]
        else:
            prev_turn[x] = 0
        last_turn[x] = i

    prev = start_numbers[-1]
    turn = len(start_numbers) + 1

    while turn <= target_turn:
        # Determine next number based on history of prev
        t1 = last_turn[prev]          # most recent turn prev was spoken
        t0 = prev_turn.get(prev, 0)  # second most recent turn prev was spoken (0 if none)

        if t0 == 0:
            nxt = 0
        else:
            nxt = t1 - t0

        # Update history for nxt at current turn
        if nxt in last_turn:
            prev_turn[nxt] = last_turn[nxt]
        else:
            prev_turn[nxt] = 0
        last_turn[nxt] = turn

        prev = nxt
        turn += 1

    return prev


def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    start_numbers = list(map(int, line.split(',')))

    # Part Two target
    target = 30000000
    ans = rambunctious_recitation(start_numbers, target)
    print(ans)

if __name__ == "__main__":
    main()

