import sys

def count_increases(depths):
    # Count how many times a depth measurement increases from the previous measurement
    increases = 0
    for i in range(1, len(depths)):
        if depths[i] > depths[i - 1]:
            increases += 1
    return increases

def main():
    # Read all input lines from standard input
    data = sys.stdin.read().strip().splitlines()
    depths = [int(line.strip()) for line in data if line.strip()]

    result = count_increases(depths)
    print(result)

if __name__ == "__main__":
    main()

