import sys

def solve():
    horizontal = 0
    depth = 0

    # Read all input lines until EOF
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue  # ignore empty lines

        cmd, num_str = line.split()
        x = int(num_str)

        # Apply command rules
        if cmd == "forward":
            horizontal += x
        elif cmd == "down":
            depth += x
        elif cmd == "up":
            depth -= x

    # Compute and output the final result
    print(horizontal * depth)

if __name__ == "__main__":
    solve()

