import sys
from collections import defaultdict

def solve(data: str) -> int:
    lines = data.splitlines()

    # Step 1: Parse draw order
    draw_line = None
    for line in lines:
        if line.strip():
            draw_line = line.strip()
            break
    if draw_line is None:
        return 0

    draws = [int(x) for x in draw_line.split(",")]

    # Step 1 (cont.): Parse boards (5x5), separated by blank lines
    boards = []
    current = []
    for line in lines[lines.index(draw_line) + 1:]:
        if not line.strip():
            if current:
                # finalize current board
                if len(current) == 5:
                    boards.append(current)
                current = []
            continue
        row = [int(x) for x in line.split()]
        if row:
            current.append(row)
            if len(current) == 5:
                boards.append(current)
                current = []

    if current and len(current) == 5:
        boards.append(current)

    bcount = len(boards)
    if bcount == 0:
        return 0

    # Step 2: Initialize tracking structures
    marked = [[[False] * 5 for _ in range(5)] for _ in range(bcount)]
    row_count = [[0] * 5 for _ in range(bcount)]
    col_count = [[0] * 5 for _ in range(bcount)]
    won = [False] * bcount

    # Step 3: Build number -> occurrences map
    pos_map = defaultdict(list)  # number -> list of (board_idx, r, c)
    for bi, board in enumerate(boards):
        for r in range(5):
            for c in range(5):
                pos_map[board[r][c]].append((bi, r, c))

    # Step 4: Simulate until first board wins
    winning_board_index = None
    winning_number = None

    for x in draws:
        if x not in pos_map:
            continue
        for bi, r, c in pos_map[x]:
            if won[bi]:
                continue
            if not marked[bi][r][c]:
                marked[bi][r][c] = True
                row_count[bi][r] += 1
                col_count[bi][c] += 1
                if row_count[bi][r] == 5 or col_count[bi][c] == 5:
                    won[bi] = True
                    winning_board_index = bi
                    winning_number = x
                    break
        if winning_board_index is not None:
            break

    # Step 5: Compute score for winning board
    if winning_board_index is None:
        return 0

    bi = winning_board_index
    sum_unmarked = 0
    for r in range(5):
        for c in range(5):
            if not marked[bi][r][c]:
                sum_unmarked += boards[bi][r][c]

    return sum_unmarked * winning_number

def main():
    data = sys.stdin.read()
    result = solve(data)
    print(result)

if __name__ == "__main__":
    main()

