import sys

def solve():
    lines = [line.rstrip("\n") for line in sys.stdin.readlines()]

    # Parse draws: first non-empty line
    draws = None
    idx = 0
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
    if idx >= len(lines):
        return
    draws = [int(x) for x in lines[idx].strip().split(",")]
    idx += 1

    boards = []
    # Parse boards: each board is 5 lines of 5 ints, separated by blank lines
    while idx < len(lines):
        # Skip blank lines
        while idx < len(lines) and lines[idx].strip() == "":
            idx += 1
        if idx >= len(lines):
            break

        board = []
        for _ in range(5):
            if idx >= len(lines):
                break
            row = [int(x) for x in lines[idx].split()]
            # Ensure row has 5 numbers (input is well-formed for this puzzle)
            if len(row) != 5:
                # If malformed, try to keep reading until we have 5 numbers
                # (robustness for irregular whitespace; not expected to trigger)
                while len(row) < 5 and idx + 1 < len(lines):
                    idx += 1
                    row += [int(x) for x in lines[idx].split()]
            board.append(row)
            idx += 1

        if len(board) == 5:
            boards.append(board)

    bcount = len(boards)
    if bcount == 0:
        return

    # pos_map[b][num] -> list of (r,c) positions where num appears on board b
    pos_map = []
    for b in range(bcount):
        mp = {}
        for r in range(5):
            for c in range(5):
                num = boards[b][r][c]
                mp.setdefault(num, []).append((r, c))
        pos_map.append(mp)

    # Marking state and row/col counts for win detection
    marked = [[[False] * 5 for _ in range(5)] for _ in range(bcount)]
    row_count = [[0] * 5 for _ in range(bcount)]
    col_count = [[0] * 5 for _ in range(bcount)]
    won = [False] * bcount

    last_winner = None
    last_called = None
    remaining = bcount

    for x in draws:
        if remaining == 0:
            break
        for b in range(bcount):
            if won[b]:
                continue
            positions = pos_map[b].get(x)
            if not positions:
                continue

            # Mark all occurrences of x on this board
            for r, c in positions:
                if not marked[b][r][c]:
                    marked[b][r][c] = True
                    row_count[b][r] += 1
                    col_count[b][c] += 1

            # Check win condition (row or column complete)
            if any(row_count[b][r] == 5 for r in range(5)) or any(col_count[b][c] == 5 for c in range(5)):
                won[b] = True
                remaining -= 1
                last_winner = b
                last_called = x

    # Compute final score for the last winning board
    b = last_winner
    sum_unmarked = 0
    for r in range(5):
        for c in range(5):
            if not marked[b][r][c]:
                sum_unmarked += boards[b][r][c]

    print(sum_unmarked * last_called)

if __name__ == "__main__":
    solve()

