import sys

def hex_to_bits(hex_str: str) -> str:
    mapping = {
        '0': "0000", '1': "0001", '2': "0010", '3': "0011",
        '4': "0100", '5': "0101", '6': "0110", '7': "0111",
        '8': "1000", '9': "1001", 'A': "1010", 'B': "1011",
        'C': "1100", 'D': "1101", 'E': "1110", 'F': "1111"
    }
    return ''.join(mapping[c] for c in hex_str.strip())

def parse_packet(bits: str, i: int):
    # Read header
    version = int(bits[i:i+3], 2)
    type_id = int(bits[i+3:i+6], 2)
    i += 6

    version_sum = version

    # Literal value
    if type_id == 4:
        literal_bits = []
        while True:
            prefix = bits[i]
            literal_bits.append(bits[i+1:i+5])
            i += 5
            if prefix == '0':
                break
        value = int(''.join(literal_bits), 2) if literal_bits else 0
        return i, version_sum, value

    # Operator packet
    length_type_id = bits[i]
    i += 1
    values = []

    if length_type_id == '0':
        total_length = int(bits[i:i+15], 2)
        i += 15
        subpacket_end = i + total_length
        while i < subpacket_end:
            i, sub_vs, sub_val = parse_packet(bits, i)
            version_sum += sub_vs
            values.append(sub_val)
        # i should be at subpacket_end by construction
    else:
        num_subpackets = int(bits[i:i+11], 2)
        i += 11
        for _ in range(num_subpackets):
            i, sub_vs, sub_val = parse_packet(bits, i)
            version_sum += sub_vs
            values.append(sub_val)

    # Compute operator value based on type_id
    if type_id == 0:
        value = sum(values)
    elif type_id == 1:
        prod = 1
        for v in values:
            prod *= v
        value = prod
    elif type_id == 2:
        value = min(values)
    elif type_id == 3:
        value = max(values)
    elif type_id == 5:
        value = 1 if values[0] > values[1] else 0
    elif type_id == 6:
        value = 1 if values[0] < values[1] else 0
    elif type_id == 7:
        value = 1 if values[0] == values[1] else 0
    else:
        value = 0

    return i, version_sum, value

def solve(hex_str: str) -> int:
    bits = hex_to_bits(hex_str)
    _, _, outer_value = parse_packet(bits, 0)
    return outer_value

def main():
    hex_str = sys.stdin.readline().strip()
    if not hex_str:
        return
    print(solve(hex_str))

if __name__ == "__main__":
    main()

