import sys
import math
from dataclasses import dataclass
from typing import Optional, List, Tuple


@dataclass
class Node:
    parent: Optional["Node"] = None
    left: Optional["Node"] = None
    right: Optional["Node"] = None
    value: Optional[int] = None  # if not None => regular number

    def is_regular(self) -> bool:
        return self.value is not None

    def depth(self) -> int:
        d = 0
        cur = self
        while cur.parent is not None:
            d += 1
            cur = cur.parent
        return d


def parse_snailfish(s: str) -> Node:
    # Parse using a stack of nodes; create nodes for '[' and numbers.
    stack: List[Node] = []
    i = 0
    root: Optional[Node] = None

    def add_child(parent: Node, child: Node):
        child.parent = parent
        if parent.left is None:
            parent.left = child
        else:
            parent.right = child

    while i < len(s):
        ch = s[i]
        if ch == '[':
            node = Node()
            if stack:
                # child will be attached when we know it's a pair element; but we can attach now
                # because pairs always appear as elements in parent.
                add_child(stack[-1], node)
            else:
                root = node
            stack.append(node)
            i += 1
        elif ch == ']':
            stack.pop()
            i += 1
        elif ch == ',':
            i += 1
        elif ch.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            num = int(s[i:j])
            node = Node(value=num)
            if not stack:
                root = node
            else:
                add_child(stack[-1], node)
            i = j
        else:
            # whitespace (shouldn't exist) or other
            i += 1

    if root is None:
        raise ValueError("Failed to parse input")
    return root


def clone_tree(node: Node) -> Node:
    # Deep copy preserving structure and parent pointers.
    if node.is_regular():
        return Node(value=node.value)
    new_node = Node()
    new_node.left = clone_tree(node.left) if node.left is not None else None
    new_node.right = clone_tree(node.right) if node.right is not None else None
    if new_node.left is not None:
        new_node.left.parent = new_node
    if new_node.right is not None:
        new_node.right.parent = new_node
    return new_node


def find_leftmost_explodable(root: Node) -> Optional[Node]:
    # Leftmost pair nested inside four pairs => depth >= 4 (root depth 0, children depth 1, etc.)
    # We need the leftmost such pair; do DFS pre-order (left before right).
    stack: List[Tuple[Node, int]] = [(root, 0)]
    while stack:
        node, _ = stack.pop()
        if node.is_regular():
            continue
        d = node.depth()
        if d >= 4:
            # This node is nested inside at least four pairs.
            return node
        # Pre-order: push right then left so left is processed first.
        if node.right is not None:
            stack.append((node.right, 0))
        if node.left is not None:
            stack.append((node.left, 0))
    return None


def find_leftmost_splittable(root: Node) -> Optional[Node]:
    # Leftmost regular number >= 10
    stack: List[Node] = [root]
    while stack:
        node = stack.pop()
        if node.is_regular():
            if node.value is not None and node.value >= 10:
                return node
        else:
            # leftmost => process left first
            if node.right is not None:
                stack.append(node.right)
            if node.left is not None:
                stack.append(node.left)
    return None


def get_first_regular_left(node: Node) -> Optional[Node]:
    # Find first regular number to the left of this node in in-order traversal.
    cur = node
    while cur.parent is not None:
        parent = cur.parent
        if parent.left is cur:
            cur = parent
            continue
        # cur is in parent's right subtree; go to parent's left subtree and then rightmost regular.
        cand = parent.left
        while cand is not None and not cand.is_regular():
            cand = cand.right
        return cand if cand is not None and cand.is_regular() else None
    return None


def get_first_regular_right(node: Node) -> Optional[Node]:
    # Find first regular number to the right of this node in in-order traversal.
    cur = node
    while cur.parent is not None:
        parent = cur.parent
        if parent.right is cur:
            cur = parent
            continue
        # cur is in parent's left subtree; go to parent's right subtree and then leftmost regular.
        cand = parent.right
        while cand is not None and not cand.is_regular():
            cand = cand.left
        return cand if cand is not None and cand.is_regular() else None
    return None


def explode(root: Node, pair_node: Node) -> None:
    # pair_node is a pair whose children are regular numbers.
    assert not pair_node.is_regular()
    assert pair_node.left is not None and pair_node.right is not None
    assert pair_node.left.is_regular() and pair_node.right.is_regular()

    left_val = pair_node.left.value
    right_val = pair_node.right.value

    left_target = get_first_regular_left(pair_node)
    if left_target is not None:
        left_target.value += left_val

    right_target = get_first_regular_right(pair_node)
    if right_target is not None:
        right_target.value += right_val

    # Replace pair_node with regular 0 in its parent.
    pair_node.left = None
    pair_node.right = None
    pair_node.value = 0


def split(root: Node, reg_node: Node) -> None:
    assert reg_node.is_regular()
    v = reg_node.value
    assert v is not None and v >= 10
    left_v = v // 2
    right_v = (v + 1) // 2

    reg_node.value = None
    reg_node.left = Node(parent=reg_node, value=left_v)
    reg_node.right = Node(parent=reg_node, value=right_v)


def reduce_snailfish(root: Node) -> Node:
    while True:
        pair = find_leftmost_explodable(root)
        if pair is not None:
            explode(root, pair)
            continue
        reg = find_leftmost_splittable(root)
        if reg is not None:
            split(root, reg)
            continue
        break
    return root


def add(a: Node, b: Node) -> Node:
    new_root = Node()
    new_root.left = clone_tree(a)
    new_root.right = clone_tree(b)
    new_root.left.parent = new_root
    new_root.right.parent = new_root
    return reduce_snailfish(new_root)


def magnitude(node: Node) -> int:
    if node.is_regular():
        return node.value
    return 3 * magnitude(node.left) + 2 * magnitude(node.right)


def main():
    lines = [line.strip() for line in sys.stdin if line.strip()]
    nums = [parse_snailfish(line) for line in lines]
    n = len(nums)
    best = -1

    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            # Add i + j (order matters)
            s = add(nums[i], nums[j])
            m = magnitude(s)
            if m > best:
                best = m

    print(best)


if __name__ == "__main__":
    main()

