import sys

def find_first_marker_position(s: str, L: int) -> int:
    n = len(s)
    if n < L:
        return -1  # Not expected for valid puzzle inputs

    freq = {}
    distinct_count = 0

    # Initialize frequency map for the first window [0, L-1]
    for ch in s[:L]:
        prev = freq.get(ch, 0)
        if prev == 0:
            distinct_count += 1
        freq[ch] = prev + 1

    # If all L characters are distinct, marker ends at position L (1-based)
    if distinct_count == L:
        return L

    # Slide the window: outgoing s[i-L], incoming s[i]
    for i in range(L, n):
        out_ch = s[i - L]
        freq[out_ch] -= 1
        if freq[out_ch] == 0:
            distinct_count -= 1
            del freq[out_ch]

        in_ch = s[i]
        prev = freq.get(in_ch, 0)
        if prev == 0:
            distinct_count += 1
        freq[in_ch] = prev + 1

        if distinct_count == L:
            # Window ends at index i, so processed characters = i + 1 (1-based)
            return i + 1

    return -1  # Not expected for valid puzzle inputs

def main():
    s = sys.stdin.readline().strip()
    L = 14  # Part Two marker length
    ans = find_first_marker_position(s, L)
    print(ans)

if __name__ == "__main__":
    main()

