import sys

def solve(lines):
    # Track direct file sizes per directory (full path -> sum of files directly inside it)
    dir_sizes_direct = {}
    # Track parent directory (full path -> full path or None for root)
    parent_of = {}

    def norm_path(parts):
        if not parts or parts == ['/']:
            return '/'
        # parts like ['/', 'a', 'e'] -> '/a/e'
        return '/' + '/'.join(p for p in parts[1:] if p)

    # Initialize root
    current_path = ['/']
    root = '/'
    dir_sizes_direct[root] = 0
    parent_of[root] = None

    # Helper to ensure a directory exists in our structures
    def ensure_dir(path_parts):
        p = norm_path(path_parts)
        if p not in dir_sizes_direct:
            dir_sizes_direct[p] = 0
            # Determine parent
            if p == '/':
                parent_of[p] = None
            else:
                parent_parts = path_parts[:-1]
                parent_of[p] = norm_path(parent_parts)
        return p

    # Ensure current directory exists
    ensure_dir(current_path)

    for line in lines:
        line = line.strip()
        if not line:
            continue

        if line.startswith('$'):
            # Command
            cmd = line[2:].strip()
            if cmd.startswith('cd '):
                arg = cmd[3:].strip()
                if arg == '/':
                    current_path = ['/']
                elif arg == '..':
                    if len(current_path) > 1:
                        current_path.pop()
                    else:
                        current_path = ['/']
                else:
                    current_path.append(arg)
                ensure_dir(current_path)
            # '$ ls' produces no direct action; its following lines are handled below
        else:
            # ls output line
            cur_dir = norm_path(current_path)
            if line.startswith('dir '):
                name = line[4:].strip()
                sub_parts = current_path + [name]
                ensure_dir(sub_parts)
            else:
                # "<size> <filename>"
                size_str, _ = line.split(' ', 1)
                size = int(size_str)
                dir_sizes_direct[cur_dir] += size

    # Compute total sizes bottom-up by propagating each directory's total to its parent
    total_size = dict(dir_sizes_direct)

    # Sort directories by depth descending (deepest first)
    # Depth: number of segments excluding leading '/'
    def depth(path):
        if path == '/':
            return 0
        return path.count('/')

    dirs = list(total_size.keys())
    dirs.sort(key=depth, reverse=True)

    for d in dirs:
        p = parent_of.get(d)
        if p is not None:
            total_size[p] += total_size[d]

    # Sum of total sizes of directories with total size at most 100000
    ans = 0
    for d, ts in total_size.items():
        if ts <= 100000:
            ans += ts

    return ans

def main():
    lines = sys.stdin.read().splitlines()
    result = solve(lines)
    sys.stdout.write(str(result))

if __name__ == "__main__":
    main()

