import sys

def solve() -> None:
    hx = hy = 0  # head position
    tx = ty = 0  # tail position

    visited = {(tx, ty)}  # tail positions visited at least once

    def sign(v: int) -> int:
        if v < 0:
            return -1
        if v > 0:
            return 1
        return 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        d, k_str = line.split()
        k = int(k_str)

        for _ in range(k):
            # Move head one step
            if d == 'R':
                hx += 1
            elif d == 'L':
                hx -= 1
            elif d == 'U':
                hy += 1
            elif d == 'D':
                hy -= 1
            else:
                continue

            # Check if tail is touching head (including diagonal and overlap)
            dx = hx - tx
            dy = hy - ty
            if abs(dx) <= 1 and abs(dy) <= 1:
                continue

            # Move tail one step toward head
            tx += sign(dx)
            ty += sign(dy)
            visited.add((tx, ty))

    print(len(visited))

if __name__ == "__main__":
    solve()

