import sys

def solve(program_lines):
    # Parse instructions: each instruction is (duration, delta)
    instructions = []
    for line in program_lines:
        line = line.strip()
        if not line:
            continue
        if line == "noop":
            instructions.append((1, 0))
        else:
            # addx V
            op, v = line.split()
            instructions.append((2, int(v)))

    # Target cycles for signal strength
    targets = {20, 60, 100, 140, 180, 220}
    sum_signals = 0

    cycle = 0  # number of cycles completed so far
    X = 1      # register starts at 1

    # Simulate cycle-by-cycle
    for duration, delta in instructions:
        for _ in range(duration):
            cycle += 1  # start of this cycle is after incrementing completed cycles
            if cycle in targets:
                sum_signals += cycle * X
                # Optional early stop once we've collected all targets
                if len(targets) == 0:
                    return sum_signals
        # After the instruction finishes, apply its delta (only for addx)
        X += delta

        # Remove collected targets to allow early stop
        # (We can't remove inside the inner loop without tracking which were collected.)
        # Instead, recompute remaining by checking membership in a set of collected cycles.
        # But since targets is small, we can do it simply:
        # We'll maintain a collected set instead.
    return sum_signals

def solve_with_early_stop(program_lines):
    instructions = []
    for line in program_lines:
        line = line.strip()
        if not line:
            continue
        if line == "noop":
            instructions.append((1, 0))
        else:
            _, v = line.split()
            instructions.append((2, int(v)))

    targets = {20, 60, 100, 140, 180, 220}
    collected = set()
    sum_signals = 0

    cycle = 0
    X = 1

    for duration, delta in instructions:
        for _ in range(duration):
            cycle += 1
            if cycle in targets and cycle not in collected:
                collected.add(cycle)
                sum_signals += cycle * X
                if len(collected) == len(targets):
                    return sum_signals
        X += delta

        if cycle >= 220 and len(collected) == len(targets):
            return sum_signals

    return sum_signals

def main():
    program_lines = sys.stdin.read().splitlines()
    # Use the early-stop version to avoid unnecessary simulation
    ans = solve_with_early_stop(program_lines)
    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()

