import sys

def solve(program_lines):
    # Parse instructions into (op, delta) where delta is applied after op finishes
    instrs = []
    for line in program_lines:
        line = line.strip()
        if not line:
            continue
        if line == "noop":
            instrs.append(("noop", 0))
        else:
            op, v = line.split()
            instrs.append((op, int(v)))

    # Part 1 sampling cycles
    sample_cycles = {20, 60, 100, 140, 180, 220}
    sum_strength = 0

    # CRT setup: 40 columns x 6 rows = 240 pixels
    width, height = 40, 6
    total_pixels = width * height
    crt = []  # store drawn pixels in order

    X = 1
    cycle = 0  # number of cycles completed so far

    for op, delta in instrs:
        duration = 1 if op == "noop" else 2

        for i in range(duration):
            # Advance one cycle
            cycle += 1

            # CRT draws exactly one pixel per cycle
            if cycle <= total_pixels:
                pos = (cycle - 1) % width  # 0..39
                # Sprite covers X-1, X, X+1
                crt.append('#' if pos in (X - 1, X, X + 1) else '.')

            # Signal strength sampled at specific cycle numbers
            if cycle in sample_cycles:
                sum_strength += cycle * X

        # Apply register update after the instruction completes
        if op == "addx":
            X += delta

    # Build CRT image (always 6 lines of 40 if program runs long enough)
    # If input is shorter, pad with '.' to reach 240 pixels.
    if len(crt) < total_pixels:
        crt.extend(['.'] * (total_pixels - len(crt)))

    lines = [''.join(crt[r * width:(r + 1) * width]) for r in range(height)]
    return "\n".join(lines)

def main():
    program_lines = sys.stdin.read().splitlines()
    output = solve(program_lines)
    sys.stdout.write(output)

if __name__ == "__main__":
    main()

