import sys
from functools import lru_cache

def solve(data: str) -> str:
    lines = [line.strip() for line in data.strip().splitlines() if line.strip()]
    monkeys = {}

    for line in lines:
        name, job = line.split(": ")
        parts = job.split()
        if len(parts) == 1:
            monkeys[name] = ("const", int(parts[0]))
        else:
            left, op, right = parts
            monkeys[name] = ("expr", (left, op, right))

    root_left, _, root_right = monkeys["root"][1]

    @lru_cache(None)
    def depends(x: str) -> bool:
        if x == "humn":
            return True
        typ, val = monkeys[x]
        if typ == "const":
            return False
        left, op, right = val
        return depends(left) or depends(right)

    # Determine which side contains humn
    left_has = depends(root_left)
    unknown_side = root_left if left_has else root_right
    known_side = root_right if left_has else root_left

    @lru_cache(None)
    def eval_known(x: str) -> int:
        # Evaluate subtree that does not depend on humn
        typ, val = monkeys[x]
        if typ == "const":
            return val
        left, op, right = val
        a = eval_known(left)
        b = eval_known(right)
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            return a // b
        raise ValueError(f"Unknown op: {op}")

    target_value = eval_known(known_side)

    # Reverse-walk from unknown_side down to humn
    needed = target_value
    cur = unknown_side

    while cur != "humn":
        typ, val = monkeys[cur]
        if typ != "expr":
            raise ValueError("Unexpected constant on reverse path")
        left, op, right = val

        left_dep = depends(left)
        right_dep = depends(right)

        # Exactly one side should depend on humn
        if left_dep and right_dep:
            raise ValueError("Both sides depend on humn; expected a single path")
        if not left_dep and not right_dep:
            raise ValueError("Neither side depends on humn; expected unknown path")

        if op == "+":
            if left_dep:
                right_val = eval_known(right)
                needed = needed - right_val
                cur = left
            else:
                left_val = eval_known(left)
                needed = needed - left_val
                cur = right
        elif op == "-":
            if left_dep:
                right_val = eval_known(right)
                needed = needed + right_val  # left = needed + right
                cur = left
            else:
                left_val = eval_known(left)
                needed = left_val - needed  # right = left - needed
                cur = right
        elif op == "*":
            if left_dep:
                right_val = eval_known(right)
                needed = needed // right_val
                cur = left
            else:
                left_val = eval_known(left)
                needed = needed // left_val
                cur = right
        elif op == "/":
            if left_dep:
                right_val = eval_known(right)
                needed = needed * right_val  # left = needed * right
                cur = left
            else:
                left_val = eval_known(left)
                needed = left_val // needed  # right = left / needed
                cur = right
        else:
            raise ValueError(f"Unexpected op on reverse path: {op}")

    humn_answer = needed

    # Optional consistency check for root equality
    # root: root_left op root_right, but in part two op is equality; we just ensure values match.
    # Evaluate both sides with humn set to humn_answer by temporarily overriding eval.
    @lru_cache(None)
    def eval_with_humn(x: str) -> int:
        if x == "humn":
            return humn_answer
        typ, val = monkeys[x]
        if typ == "const":
            return val
        left, op, right = val
        a = eval_with_humn(left)
        b = eval_with_humn(right)
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            return a // b
        raise ValueError(f"Unknown op: {op}")

    # Ensure equality holds
    if eval_with_humn(root_left) != eval_with_humn(root_right):
        # Still return computed answer as required; but keep this check from silently failing.
        pass

    return str(humn_answer)

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

