import sys

def snafu_to_decimal(s: str) -> int:
    """Convert a SNAFU string to its decimal integer value."""
    mapping = {'2': 2, '1': 1, '0': 0, '-': -1, '=': -2}
    value = 0
    for c in s.strip():
        value = value * 5 + mapping[c]
    return value

def decimal_to_snafu(n: int) -> str:
    """Convert a decimal integer to its SNAFU string representation."""
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        r = n % 5
        if r == 0:
            digits.append('0')
            n //= 5
        elif r == 1:
            digits.append('1')
            n //= 5
        elif r == 2:
            digits.append('2')
            n //= 5
        elif r == 3:
            # remainder 3 corresponds to -2 with a carry
            digits.append('=')
            n = (n + 2) // 5
        else:  # r == 4
            # remainder 4 corresponds to -1 with a carry
            digits.append('-')
            n = (n + 1) // 5

    return ''.join(reversed(digits))

def solve() -> None:
    lines = [line.strip() for line in sys.stdin.read().splitlines()]
    snafus = [line for line in lines if line]  # ignore empty lines

    total = 0
    for s in snafus:
        total += snafu_to_decimal(s)

    print(decimal_to_snafu(total))

if __name__ == "__main__":
