import sys

def count_arrangements(pattern: str, groups: list[int]) -> int:
    n = len(pattern)
    k = len(groups)

    # Precompute suffix_has_hash[i] = whether pattern[i:] contains any '#'
    suffix_has_hash = [False] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_has_hash[i] = suffix_has_hash[i + 1] or (pattern[i] == '#')

    # Precompute canPlace[i][j]:
    # whether group j (length L=groups[j]) can be placed starting at i
    # respecting:
    # - substring i..i+L-1 contains no '.'
    # - if not last group, char at i+L must be '.' or '?' (separator)
    canPlace = [[False] * k for _ in range(n + 1)]
    for j in range(k):
        L = groups[j]
        for i in range(n + 1):
            if i + L > n:
                continue
            ok = True
            # substring must be all '#' or '?'
            for t in range(i, i + L):
                if pattern[t] == '.':
                    ok = False
                    break
            if not ok:
                continue
            if j < k - 1:
                # need at least one separator char after the run
                if i + L >= n:
                    continue
                if pattern[i + L] == '#':
                    continue
            canPlace[i][j] = True

    # dp[i][j] where:
    # i = current index in pattern (0..n)
    # j = next group index to place (0..k)
    # dp[i][j] = number of ways to satisfy groups[j:] using pattern[i:]
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base: when all groups placed (j==k), remaining suffix must contain no '#'
    for i in range(n + 1):
        dp[i][k] = 0 if suffix_has_hash[i] else 1

    # Fill from end to start
    for i in range(n - 1, -1, -1):
        for j in range(k - 1, -1, -1):
            ways = 0

            # Option 1: treat pattern[i] as operational '.'
            if pattern[i] in '.?':
                ways += dp[i + 1][j]

            # Option 2: place group j starting at i
            if canPlace[i][j]:
                L = groups[j]
                if j < k - 1:
                    next_i = i + L + 1  # skip separator char
                else:
                    next_i = i + L
                if next_i <= n:
                    ways += dp[next_i][j + 1]

            dp[i][j] = ways

    return dp[0][0]


def solve() -> None:
    lines = [line.strip() for line in sys.stdin if line.strip()]
    total = 0
    for line in lines:
        left, right = line.split()
        pattern = left
        groups = list(map(int, right.split(',')))
        total += count_arrangements(pattern, groups)
    print(total)


if __name__ == "__main__":
    solve()

