from functools import lru_cache

def count_arrangements(pattern: str, groups: list[int]) -> int:
    n = len(pattern)
    m = len(groups)

    # Precompute can_place[i][j] = whether group j can start at position i
    # group j has length L = groups[j]
    can_place = [[False] * m for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(m):
            L = groups[j]
            end = i + L
            if end > n:
                continue

            # All cells in the group must be '#' or '?'
            ok = True
            for t in range(i, end):
                if pattern[t] == '.':
                    ok = False
                    break
            if not ok:
                continue

            # Need at least one '.' separator after the group if it doesn't end at n
            if end < n and pattern[end] == '#':
                continue

            can_place[i][j] = True

    @lru_cache(maxsize=None)
    def dp(i: int, j: int) -> int:
        # i: current index in pattern
        # j: number of groups already placed
        if j == m:
            # No more groups: remaining suffix must not contain forced '#'
            for t in range(i, n):
                if pattern[t] == '#':
                    return 0
            return 1

