        # Option B: place next group starting at i
        if i <= n and can_place[i][j]:
            L = groups[j]
            end = i + L
            if end == n:
                total += dp(end, j + 1)
            else:
                # Consume one separator position (must be '.' or '?', ensured by can_place)
                total += dp(end + 1, j + 1)

        return total

    return dp(0, 0)

