def find_vertical_reflection(pattern):
    R = len(pattern)
    C = len(pattern[0]) if R else 0

    for k in range(1, C):  # between columns k-1 and k (1-based left count = k)
        ok = True
        for r in range(R):
            d = 0
            while True:
                L = k - 1 - d
                RR = k + d
                if L < 0 or RR >= C:
                    break  # this side has no counterpart; allowed
                if pattern[r][L] != pattern[r][RR]:
                    ok = False
                    break
                d += 1
            if not ok:
                break
        if ok:
            return k
    return 0

