    R = len(pattern)
    C = len(pattern[0]) if R else 0

    for k in range(1, R):  # between rows k-1 and k (1-based above count = k)
        ok = True
        for c in range(C):
            d = 0
            while True:
                U = k - 1 - d
                D = k + d
                if U < 0 or D >= R:
