import sys

def parse_patterns(lines):
    patterns = []
    cur = []
    for line in lines:
        line = line.rstrip("\n")
        if not line.strip():
            if cur:
                patterns.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        patterns.append(cur)
    return patterns

def reflection_mismatches_vertical(grid, k):
    """
    Candidate vertical reflection line between columns k-1 and k (k in 1..C-1).
    Count mismatched mirrored cell pairs across this line.
    """
    R = len(grid)
    C = len(grid[0])
    left = k - 1
    right = k
    span = min(left + 1, C - right)  # number of columns to compare on each side
    mism = 0
    for r in range(R):
        row = grid[r]
        for d in range(span):
            if row[left - d] != row[right + d]:
                mism += 1
    return mism

def reflection_mismatches_horizontal(grid, k):
    """
    Candidate horizontal reflection line between rows k-1 and k (k in 1..R-1).
    Count mismatched mirrored cell pairs across this line.
    """
    R = len(grid)
    C = len(grid[0])
    top = k - 1
    bottom = k
    span = min(top + 1, R - bottom)
    mism = 0
    for c in range(C):
        for d in range(span):
            if grid[top - d][c] != grid[bottom + d][c]:
                mism += 1
    return mism

def find_perfect_reflection(grid):
    """
    Part 1: find the perfect reflection line (mismatches == 0).
    Returns (orientation, k) where orientation is 'V' or 'H'.
    """
    R = len(grid)
    C = len(grid[0])

    for k in range(1, C):
        if reflection_mismatches_vertical(grid, k) == 0:
            return ('V', k)
    for k in range(1, R):
        if reflection_mismatches_horizontal(grid, k) == 0:
            return ('H', k)
    return None

def solve_part2(patterns):
    ans = 0
    for grid in patterns:
        R = len(grid)
        C = len(grid[0])

        old = find_perfect_reflection(grid)  # (orientation, k)
        old_orient, old_k = old

        new_found = None

        # Try vertical candidates first
        for k in range(1, C):
            if old_orient == 'V' and k == old_k:
                continue
            if reflection_mismatches_vertical(grid, k) == 1:
                new_found = ('V', k)
                break

        # If not found, try horizontal candidates
        if new_found is None:
            for k in range(1, R):
                if old_orient == 'H' and k == old_k:
                    continue
                if reflection_mismatches_horizontal(grid, k) == 1:
                    new_found = ('H', k)
                    break

        orient, k = new_found
        if orient == 'V':
            ans += k
        else:
            ans += 100 * k

    return ans

def main():
    lines = sys.stdin.read().splitlines()
    patterns = parse_patterns(lines)
    print(solve_part2(patterns))

if __name__ == "__main__":
    main()

