import sys

def tilt(grid, direction):
    """
    Tilt the platform in one of four directions: 'N', 'W', 'S', 'E'.
    Cube rocks '#' stay fixed; rounded rocks 'O' slide until blocked.
    """
    R = len(grid)
    C = len(grid[0])
    # Work on a mutable copy
    new_grid = [row[:] for row in grid]

    if direction == 'N':
        for c in range(C):
            write = 0
            for r in range(R):
                if grid[r][c] == '#':
                    write = r + 1
                elif grid[r][c] == 'O':
                    # Move rock to the current write position
                    new_grid[r][c] = '.'
                    new_grid[write][c] = 'O'
                    write += 1

    elif direction == 'S':
        for c in range(C):
            write = R - 1
            for r in range(R - 1, -1, -1):
                if grid[r][c] == '#':
                    write = r - 1
                elif grid[r][c] == 'O':
                    new_grid[r][c] = '.'
                    new_grid[write][c] = 'O'
                    write -= 1

    elif direction == 'W':
        for r in range(R):
            write = 0
            for c in range(C):
                if grid[r][c] == '#':
                    write = c + 1
                elif grid[r][c] == 'O':
                    new_grid[r][c] = '.'
                    new_grid[r][write] = 'O'
                    write += 1

    elif direction == 'E':
        for r in range(R):
            write = C - 1
            for c in range(C - 1, -1, -1):
                if grid[r][c] == '#':
                    write = c - 1
                elif grid[r][c] == 'O':
                    new_grid[r][c] = '.'
                    new_grid[r][write] = 'O'
                    write -= 1
    else:
        raise ValueError("Invalid direction")

    return new_grid

def spin_cycle(grid):
    # One full cycle: North, West, South, East
    grid = tilt(grid, 'N')
    grid = tilt(grid, 'W')
    grid = tilt(grid, 'S')
    grid = tilt(grid, 'E')
    return grid

def load_north(grid):
    # Load is sum over 'O' of (rows from rock to south edge, including its row)
    R = len(grid)
    total = 0
    for r in range(R):
        row = grid[r]
        # Each 'O' at row r contributes (R - r)
        cnt = row.count('O')
        total += cnt * (R - r)
    return total

def grid_to_state(grid):
    # Encode entire grid as a single string for exact state matching
    return ''.join(''.join(row) for row in grid)

def solve(grid, target_cycles=1_000_000_000):
    seen = {}
    states = []

    state = grid_to_state(grid)
    seen[state] = 0
    states.append(state)

    i = 0
    while True:
        # Advance one cycle
        grid = spin_cycle(grid)
        i += 1
        state = grid_to_state(grid)

        if state in seen:
            start = seen[state]
            cycle_len = i - start
            # Determine which state corresponds to target_cycles
            # target_cycles counts cycles from the initial state (cycle 0)
            effective = start + (target_cycles - start) % cycle_len
            # Reconstruct grid from stored state to compute load
            # (We can compute load directly from state string too, but reconstructing is simple.)
            chosen_state = states[effective]
            R = len(grid)
            C = len(grid[0])
            chosen_grid = [list(chosen_state[r*C:(r+1)*C]) for r in range(R)]
            return load_north(chosen_grid)

        seen[state] = i
        states.append(state)

def main():
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip('\n') != '']
    if not lines:
        return
    grid = [list(line) for line in lines]
    ans = solve(grid, 1_000_000_000)
    print(ans)

if __name__ == "__main__":
    main()

