import sys

def holiday_hash(s: str) -> int:
    cur = 0
    for ch in s:
        cur += ord(ch)
        cur *= 17
        cur %= 256
    return cur

def solve():
    line = sys.stdin.read().strip()
    if not line:
        return

    steps = [tok for tok in line.split(',') if tok != '']

    # Part Two: 256 boxes, each box holds lenses as (label, focal_length) in order
    boxes = [[] for _ in range(256)]

    for step in steps:
        if step.endswith('-'):
            label = step[:-1]
            box_idx = holiday_hash(label)
            box = boxes[box_idx]

            # Remove lens with matching label if present
            for i, (lab, _) in enumerate(box):
                if lab == label:
                    del box[i]
                    break
        else:
            label, focal_str = step.split('=')
            focal = int(focal_str)
            box_idx = holiday_hash(label)
            box = boxes[box_idx]

            # Replace if label exists; otherwise append
            for i, (lab, _) in enumerate(box):
                if lab == label:
                    box[i] = (label, focal)
                    break
            else:
                box.append((label, focal))

    # Compute focusing power
    total_power = 0
    for b in range(256):
        for slot_idx, (_, focal) in enumerate(boxes[b]):
