import sys
from typing import List, Optional, Tuple

def is_safe(levels: List[int]) -> bool:
    n = len(levels)
    if n <= 2:
        return True

    # Determine direction from first non-zero adjacent difference
    direction = 0  # 0 unknown, +1 increasing, -1 decreasing
    for i in range(n - 1):
        diff = levels[i + 1] - levels[i]
        if diff != 0:
            direction = 1 if diff > 0 else -1
            break

    if direction == 0:
        return False  # all equal => adjacent diff is 0 (invalid)

    for i in range(n - 1):
        diff = levels[i + 1] - levels[i]
        if direction == 1:
            if not (1 <= diff <= 3):
                return False
        else:
            if not (-3 <= diff <= -1):
                return False
    return True


def can_be_safe_with_dampener(levels: List[int]) -> bool:
    n = len(levels)
    if n <= 2:
        return True

    # Try to validate with at most one removal using a single branching at first violation.
    # We'll implement a helper that checks safety when skipping at most one index.
    # To keep it simple and robust, we branch once at the first violation:
    # - remove current element
    # - remove previous element
    #
    # Each branch is validated in O(n) with a "skip index" parameter.
    def check_with_skip(skip_idx: Optional[int]) -> bool:
        prev_idx = None
        direction = 0  # 0 unknown, +1 increasing, -1 decreasing

        for i in range(n):
            if skip_idx is not None and i == skip_idx:
                continue
            if prev_idx is None:
                prev_idx = i
                continue

            prev_val = levels[prev_idx]
            cur_val = levels[i]
            diff = cur_val - prev_val

            if diff == 0:
                return False

            if direction == 0:
                direction = 1 if diff > 0 else -1

            if direction == 1:
                if not (1 <= diff <= 3):
                    return False
            else:
                if not (-3 <= diff <= -1):
                    return False

            prev_idx = i

        # If we skipped everything but one element, it's trivially safe
        return True

    if is_safe(levels):
        return True

    # Branch: remove one index (try all indices is O(n^2); instead branch at first violation)
    # We'll find the first violation in the original sequence and branch on removing one of the two elements involved.
    # If direction is unknown due to initial equals, we still can find a violation by simulating with no skip.
    # We'll do a direct scan to locate the first invalid adjacent pair under the best possible direction inference.
    # For simplicity, we just try removing the two candidates around the first definite violation found
    # by checking safety after removing each candidate; this is still O(n) overall because we only do two checks.
    #
    # Find first index where removing either i or i-1 could help by locating a violation in the "no removal" attempt.
    # We'll compute direction as in is_safe, then find first failing pair.
    direction = 0
    for i in range(n - 1):
        diff = levels[i + 1] - levels[i]
        if diff != 0:
            direction = 1 if diff > 0 else -1
            break

    # If direction is 0, all equal => removing one still leaves all equal (unless length becomes 2, but diff still 0)
    if direction == 0:
        return False

    fail_i = None
    for i in range(n - 1):
        diff = levels[i + 1] - levels[i]
        if direction == 1:
            if not (1 <= diff <= 3):
                fail_i = i
                break
        else:
            if not (-3 <= diff <= -1):
                fail_i = i
                break

    if fail_i is None:
        return True  # should not happen since is_safe(levels) was false

    # Candidates: remove levels[fail_i] or levels[fail_i+1]
    return check_with_skip(fail_i) or check_with_skip(fail_i + 1)


def solve(data: str) -> str:
    reports = []
    for line in data.splitlines():
        line = line.strip()
        if not line:
            continue
        reports.append([int(x) for x in line.split()])

    safe_count = 0
    for levels in reports:
        if is_safe(levels) or can_be_safe_with_dampener(levels):
            safe_count += 1

    return str(safe_count)


def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

