import sys

def count_word_occurrences(grid, word="XMAS"):
    if not grid:
        return 0
    R = len(grid)
    C = len(grid[0])
    L = len(word)

    directions = [
        (0, 1),   # right
        (0, -1),  # left
        (1, 0),   # down
        (-1, 0),  # up
        (1, 1),   # down-right
        (1, -1),  # down-left
        (-1, 1),  # up-right
        (-1, -1), # up-left
    ]

    count = 0
    for r in range(R):
        for c in range(C):
            for dr, dc in directions:
                r_end = r + (L - 1) * dr
                c_end = c + (L - 1) * dc
                if not (0 <= r_end < R and 0 <= c_end < C):
                    continue

                ok = True
                for i in range(L):
                    if grid[r + i * dr][c + i * dc] != word[i]:
                        ok = False
                        break
                if ok:
                    count += 1
    return count

def main():
    lines = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    grid = [list(line.strip()) for line in lines if line.strip() != ""]
    print(count_word_occurrences(grid, "XMAS"))

if __name__ == "__main__":
    main()

