import sys

def solve(data: str) -> int:
    lines = [line.strip() for line in data.splitlines()]
    lines = [line for line in lines if line != ""]

    rules = []
    updates = []

    # Detect transition between rules and updates.
    # Rules lines contain '|', updates lines contain ','.
    in_updates = False
    for line in lines:
        if not in_updates and '|' in line:
            x, y = line.split('|', 1)
            rules.append((int(x), int(y)))
        else:
            in_updates = True
            updates.append(line)

    # before[X] = set of Y such that X must be printed before Y
    before = {}
    for x, y in rules:
        before.setdefault(x, set()).add(y)

    total = 0

    for upd in updates:
        pages = [int(x) for x in upd.split(',') if x != ""]
        pos = {}
        for i, p in enumerate(pages):
            # Assume unique pages per update (as per puzzle). If duplicates exist,
            # keep the first occurrence as a conservative choice.
            if p not in pos:
                pos[p] = i

        valid = True
        # Check only relevant edges: for each X present, consider Y in before[X]
        # and verify that if Y is also present, pos[X] < pos[Y].
        for x in pages:
            if x not in before:
                continue
            px = pos.get(x)
            for y in before[x]:
                py = pos.get(y)
                if py is not None and px >= py:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            mid_index = len(pages) // 2
            total += pages[mid_index]

    return total

def main():
    data = sys.stdin.read()
    ans = solve(data)
    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    main()

