import sys
import heapq
from collections import defaultdict

def parse_input(lines):
    rules = []
    updates = []
    section = 0  # 0 = rules, 1 = updates
    for raw in lines:
        line = raw.strip()
        if not line:
            section = 1
            continue
        if section == 0:
            x_str, y_str = line.split('|')
            rules.append((int(x_str), int(y_str)))
        else:
            pages = [int(x) for x in line.split(',') if x.strip() != '']
            if pages:
                updates.append(pages)
    return rules, updates

def is_correct_order(pages, after):
    # Build position map for O(1) index lookup
    pos = {p: i for i, p in enumerate(pages)}
    in_update = set(pos.keys())

    # For each page X, check all Y that must come after X (only if Y is in this update)
    for x in pages:
        for y in after.get(x, ()):
            if y in in_update and pos[x] >= pos[y]:
                return False
    return True

def corrected_order(pages, after):
    # Induce subgraph on pages appearing in this update
    nodes = set(pages)
    indeg = {n: 0 for n in nodes}
    adj = defaultdict(list)

    for x in nodes:
        for y in after.get(x, ()):
            if y in nodes:
                adj[x].append(y)
                indeg[y] += 1

    # Deterministic topological sort: smallest page first among indegree-0 nodes
    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)

    sorted_pages = []
    while heap:
        u = heapq.heappop(heap)
        sorted_pages.append(u)
        for v in adj.get(u, ()):
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    # If cycle exists, sorted_pages would be incomplete; puzzle inputs should avoid this.
    if len(sorted_pages) != len(nodes):
        # Fallback: return original pages (should not happen for valid puzzle inputs)
        return pages[:]

    return sorted_pages

def solve(data):
    rules, updates = parse_input(data)

    # after[X] = set of pages Y such that X must be printed before Y
    after = defaultdict(set)
    for x, y in rules:
        after[x].add(y)

    sum_incorrect = 0

    for pages in updates:
        if is_correct_order(pages, after):
            continue
        fixed = corrected_order(pages, after)
        sum_incorrect += fixed[len(fixed) // 2]

    return str(sum_incorrect)

def main():
    data = sys.stdin.read().splitlines()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

