import sys
from typing import Dict, List

class TrieNode:
    __slots__ = ("children", "is_end")
    def __init__(self):
        self.children: Dict[str, "TrieNode"] = {}
        self.is_end: bool = False

def solve() -> None:
    lines = [line.rstrip("\n") for line in sys.stdin.readlines()]
    if not lines:
        return

    # Parse patterns (first non-empty line)
    idx = 0
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
    if idx >= len(lines):
        return

    patterns_line = lines[idx].strip()
    patterns = [p.strip() for p in patterns_line.split(",") if p.strip() != ""]
    idx += 1

    # Skip blank lines
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1

    # Remaining lines are designs
    designs: List[str] = []
    while idx < len(lines):
        s = lines[idx].strip()
        if s != "":
            designs.append(s)
        idx += 1

    # Build trie of patterns
    root = TrieNode()
    for pat in patterns:
        node = root
        for ch in pat:
            nxt = node.children.get(ch)
            if nxt is None:
                nxt = TrieNode()
                node.children[ch] = nxt
            node = nxt
        node.is_end = True

    total_ways = 0

    # For each design, compute number of ways using DP + trie traversal
    for s in designs:
        n = len(s)
        dp = [0] * (n + 1)
        dp[n] = 1  # one way to complete empty suffix

        # dp[i] = number of ways to form s[i:]
        for i in range(n - 1, -1, -1):
            node = root
            # Traverse trie along s[i:], stopping when no further prefix exists
            for k in range(i, n):
                ch = s[k]
                node = node.children.get(ch)
                if node is None:
                    break
                if node.is_end:
                    dp[i] += dp[k + 1]

        total_ways += dp[0]

    sys.stdout.write(str(total_ways))

if __name__ == "__main__":
    solve()

