import sys
from collections import deque

def bfs(grid, start):
    R, C = len(grid), len(grid[0])
    INF = 10**18
    dist = [[INF] * C for _ in range(R)]
    sr, sc = start
    dist[sr][sc] = 0
    q = deque([(sr, sc)])
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    while q:
        r, c = q.popleft()
        nd = dist[r][c] + 1
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != '#':
                if nd < dist[nr][nc]:
                    dist[nr][nc] = nd
                    q.append((nr, nc))
    return dist

def solve():
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip('\n') != '']
    if not lines:
        return
    grid = [list(line) for line in lines]
    R, C = len(grid), len(grid[0])

    S = E = None
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                S = (r, c)
            elif grid[r][c] == 'E':
                E = (r, c)

    if S is None or E is None:
        print(0)
        return

    distS = bfs(grid, S)
    distE = bfs(grid, E)
    INF = 10**18
    base = distS[E[0]][E[1]]
    if base >= INF:
        print(0)
        return

    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    ans = 0

    # Enumerate cheat start positions a (reachable normally)
    for a_r in range(R):
        for a_c in range(C):
            da = distS[a_r][a_c]
            if da >= INF:
                continue
            # k = 1 cheats: end b is a 1-step neighbor
            for dr, dc in dirs:
                b_r, b_c = a_r + dr, a_c + dc
                if not (0 <= b_r < R and 0 <= b_c < C):
                    continue
                if grid[b_r][b_c] == '#':
                    continue
                db = distE[b_r][b_c]
                if db >= INF:
                    continue
                saved = base - (da + 1 + db)
                if saved >= 100:
                    ans += 1

            # k = 2 cheats: end b is 2 steps away (via any intermediate cells)
            # Deduplicate by endpoint b for this (a, k=2).
            endpoints = set()
            for dr1, dc1 in dirs:
                m_r, m_c = a_r + dr1, a_c + dc1
                if not (0 <= m_r < R and 0 <= m_c < C):
                    continue
                for dr2, dc2 in dirs:
                    b_r, b_c = m_r + dr2, m_c + dc2
                    if not (0 <= b_r < R and 0 <= b_c < C):
                        continue
                    if grid[b_r][b_c] == '#':
                        continue
                    endpoints.add((b_r, b_c))

            for b_r, b_c in endpoints:
                db = distE[b_r][b_c]
                if db >= INF:
                    continue
                saved = base - (da + 2 + db)
                if saved >= 100:
                    ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

