import sys
from collections import deque

def solve(inp: str) -> str:
    lines = [line.rstrip("\n") for line in inp.splitlines() if line.strip("\n") != ""]
    if not lines:
        return "0"
    R, C = len(lines), len(lines[0])
    grid = [list(row) for row in lines]

    sr = sc = er = ec = -1
    track = [[False] * C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            ch = grid[r][c]
            if ch == 'S':
                sr, sc = r, c
                track[r][c] = True
            elif ch == 'E':
                er, ec = r, c
                track[r][c] = True
            elif ch == '.':
                track[r][c] = True

    INF = 10**18

    def bfs_from(start_r, start_c):
        dist = [[INF] * C for _ in range(R)]
        q = deque()
        dist[start_r][start_c] = 0
        q.append((start_r, start_c))
        while q:
            r, c = q.popleft()
            d = dist[r][c]
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and track[nr][nc]:
                    if dist[nr][nc] > d + 1:
                        dist[nr][nc] = d + 1
                        q.append((nr, nc))
        return dist

    distS = bfs_from(sr, sc)
    distE = bfs_from(er, ec)
    base = distS[er][ec]
    if base >= INF:
        return "0"

    # Collect all track cells as possible cheat start positions
    track_cells = [(r, c) for r in range(R) for c in range(C) if track[r][c]]

    T = 20
    threshold = 100

    qualifying = set()  # (start_cell, end_cell) pairs

    # For each start cell a, BFS on full grid (walls passable) up to depth T.
    # When reaching a track cell b, compute savings using minimal t from BFS.
    for ar, ac in track_cells:
        if distS[ar][ac] >= INF:
            continue

        seen = [[-1] * C for _ in range(R)]
        q = deque()
        seen[ar][ac] = 0
        q.append((ar, ac))

        while q:
            r, c = q.popleft()
            t = seen[r][c]
            if t > T:
                continue

            if track[r][c] and distE[r][c] < INF:
                total = distS[ar][ac] + t + distE[r][c]
                save = base - total
                if save >= threshold:
                    qualifying.add(((ar, ac), (r, c)))

            if t == T:
                continue

            nt = t + 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and seen[nr][nc] == -1:
                    seen[nr][nc] = nt
                    q.append((nr, nc))

    return str(len(qualifying))

def main():
    data = sys.stdin.read()
    sys.stdout.write(solve(data))

if __name__ == "__main__":
    main()

