import sys
import re

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    max_len = max(len(s) for s in lines)
    padded = [s.ljust(max_len) for s in lines]
    R = len(padded)
    C = max_len

    # Identify separator columns: columns that are spaces in every row
    is_sep = [True] * C
    for c in range(C):
        for r in range(R):
            if padded[r][c] != ' ':
                is_sep[c] = False
                break

    # Split into blocks of consecutive non-separator columns
    blocks = []
    c = 0
    while c < C:
        while c < C and is_sep[c]:
            c += 1
        if c >= C:
            break
        start = c
        while c < C and not is_sep[c]:
            c += 1
        end = c - 1
        blocks.append((start, end))

    grand_total = 0

    digit_re = re.compile(r'\d+')

    for start_col, end_col in blocks:
        numbers = []
        op = None

        # Extract per row: either digits (number) or operation (+/*)
        for r in range(R):
            segment = padded[r][start_col:end_col + 1]

            if '+' in segment:
                op = '+'
            if '*' in segment:
                op = '*'

            # Extract all digit groups in this row segment; worksheet numbers are vertical,
            # but alignment is ignored, so we take any digit groups found.
            # If multiple groups appear in a row, concatenate them in reading order.
            groups = digit_re.findall(segment)
            if groups:
                # Join groups to be robust against unexpected spacing within the segment
                # (shouldn't happen in valid inputs, but keeps parsing safe).
                num_str = ''.join(groups)
                numbers.append(int(num_str))

        if not numbers or op is None:
            continue

        if op == '+':
            grand_total += sum(numbers)
        else:
            prod = 1
            for x in numbers:
                prod *= x
            grand_total += prod

    sys.stdout.write(str(grand_total))

if __name__ == "__main__":
    solve()

