import sys

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    H = len(lines)
    maxLen = max(len(line) for line in lines)

    # Pad lines to allow safe indexing by column
    grid = [list(line.ljust(maxLen)) for line in lines]

    # Determine which columns contain any non-space character
    col_has_content = [False] * maxLen
    for c in range(maxLen):
        for r in range(H):
            if grid[r][c] != ' ':
                col_has_content[c] = True
                break

    # Group contiguous non-space columns into problem blocks
    problems = []
    c = 0
    while c < maxLen:
        if not col_has_content[c]:
            c += 1
            continue
        start = c
        while c < maxLen and col_has_content[c]:
            c += 1
        end = c - 1
        problems.append((start, end))

    grand_total = 0

    for start, end in problems:
        # Identify operator column: the one with '+' or '*' at bottom row
        op = None
        op_col = None
        bottom_r = H - 1
        for cc in range(start, end + 1):
            ch = grid[bottom_r][cc]
            if ch == '+' or ch == '*':
                op = ch
                op_col = cc
                break

        if op is None or op_col is None:
            # Invalid/empty block; skip safely
            continue

        # Extract numbers from number columns (exclude operator column)
        # Part Two: read operands right-to-left by columns
        nums = []
        for cc in range(end, start - 1, -1):
            if cc == op_col:
                continue
            digits = []
            for r in range(0, bottom_r):
                ch = grid[r][cc]
                if ch.isdigit():
                    digits.append(ch)
            if digits:
                nums.append(int(''.join(digits)))
            else:
                # Shouldn't happen for valid input; treat as 0
                nums.append(0)

        if op == '+':
            grand_total += sum(nums)
        else:  # op == '*'
            prod = 1
            for x in nums:
                prod *= x
            grand_total += prod

    sys.stdout.write(str(grand_total))

if __name__ == "__main__":
    solve()

