            if cc == op_col:
                continue
            digits = []
            for r in range(0, bottom_r):
                ch = grid[r][cc]
                if ch.isdigit():
                    digits.append(ch)
            if digits:
                nums.append(int(''.join(digits)))
            else:
                # Shouldn't happen for valid input; treat as 0
                nums.append(0)

        if op == '+':
            grand_total += sum(nums)
        else:  # op == '*'
            prod = 1
            for x in nums:
                prod *= x
            grand_total += prod

    sys.stdout.write(str(grand_total))

if __name__ == "__main__":
    solve()

