import sys
from collections import deque

def solve():
    lines = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    if not lines:
        return

    R = len(lines)
    C = max(len(line) for line in lines)
    grid = [list(line.ljust(C, '.')) for line in lines]

    start_r = start_c = None
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                start_r, start_c = r, c
                grid[r][c] = '.'

    # Precompute next splitter below for each cell:
    # next_split[r][c] = smallest k >= r such that grid[k][c] == '^', else -1
    next_split = [[-1] * C for _ in range(R + 1)]
    for c in range(C):
        nearest = -1
        for r in range(R - 1, -1, -1):
            if grid[r][c] == '^':
                nearest = r
            next_split[r][c] = nearest
        next_split[R][c] = -1

    splits = 0
    q = deque()

    # Initial beam starts moving downward from just below S
    init_r = start_r + 1
    if 0 <= init_r < R:
        q.append((init_r, start_c))

    while q:
        r, c = q.popleft()
        if not (0 <= r < R and 0 <= c < C):
            continue

        k = next_split[r][c]
        if k == -1:
            continue  # exits manifold without splitting

        # Beam encounters a splitter at (k, c)
        splits += 1

        # New beams start from immediate left/right of splitter, one row below
        nr = k + 1
        if nr < R:
            if c - 1 >= 0:
                q.append((nr, c - 1))
            if c + 1 < C:
                q.append((nr, c + 1))

    sys.stdout.write(str(splits))

if __name__ == "__main__":
    solve()

