import sys
from functools import lru_cache

def solve():
    lines = [line.rstrip("\n") for line in sys.stdin if line.strip("\n") != ""]
    if not lines:
        return
    H = len(lines)
    W = len(lines[0])

    grid = [list(row) for row in lines]
    sr = sc = None
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                sr, sc = r, c
                grid[r][c] = '.'

    # Precompute next splitter row below each cell in the same column.
    # nextSplit[r][c] = smallest r' > r with grid[r'][c] == '^', else -1.
    nextSplit = [[-1] * W for _ in range(H)]
    for c in range(W):
        last = -1
        for r in range(H - 1, -1, -1):
            nextSplit[r][c] = last
            if grid[r][c] == '^':
                last = r

    sys.setrecursionlimit(1_000_000)

    @lru_cache(maxsize=None)
    def timelines(r, c):
        # If beam goes out of horizontal bounds, it exits the manifold.
        if c < 0 or c >= W:
            return 1
        # If starting row is beyond grid, it has exited vertically.
        if r >= H:
            return 1

        hit = nextSplit[r][c]
        if hit == -1:
            return 1  # no splitter below; exits without further branching

        # At splitter (hit, c), particle branches left and right.
        return timelines(hit, c - 1) + timelines(hit, c + 1)

    ans = timelines(sr, sc)
    print(ans)

if __name__ == "__main__":
    solve()

